import java.util.concurrent.ConcurrentHashMap;

public class ThreadResourceManager {
    private Map<String, Thread> threadMap;

    public ThreadResourceManager() {
        // Using ConcurrentHashMap for thread safety
        this.threadMap = new ConcurrentHashMap<>();
    }

    public boolean createDaemonThread(String threadName, Runnable task) {
        // Check for null parameters
        if (threadName == null || task == null) {
            return false;
        }

        // Create a new thread with the given name and task
        Thread thread = new Thread(task, threadName);

        // Set the thread as a daemon thread
        thread.setDaemon(true);

        // Start the thread
        thread.start();

        // Store the thread in the internal map
        threadMap.put(threadName, thread);

        return true;
    }

    // Optional: Method to get thread by name
    public Thread getThread(String threadName) {
        return threadMap.get(threadName);
    }

    // Optional: Method to get all threads
    public Map<String, Thread> getAllThreads() {
        return new HashMap<>(threadMap);
    }
}

