import java.util.List;
import java.util.Map;
import java.util.HashMap;
import java.util.Collections;
import java.util.stream.Collectors;
import java.util.Optional;

class LogAnalyzer {

    public Map<String, Object> analyzeLogs(List<SysLog> logs) {
        Map<String, Object> result = new HashMap<>();

        if (logs == null || logs.isEmpty()) {
            result.put("error", "No logs provided for analysis");
            return result;
        }

        result.put("totalLogs", logs.size());

        Map<String, Long> userFrequency = logs.stream()
            .collect(Collectors.groupingBy(SysLog::getUsername, Collectors.counting()));

        result.put("userFrequency", userFrequency);

        String mostActiveUser = userFrequency.entrySet().stream()
            .max(Map.Entry.comparingByValue())
            .map(Map.Entry::getKey)
            .orElse(null);

        result.put("mostActiveUser", mostActiveUser);

        Optional<Long> earliestLog = logs.stream()
            .map(SysLog::getTime)
            .min(Long::compareTo);

        Optional<Long> latestLog = logs.stream()
            .map(SysLog::getTime)
