public class Venue {
    private int rows;
    private int columns;
    private boolean[][] seats;

    public Venue(int rows, int columns) {
        this.rows = rows;
        this.columns = columns;
        this.seats = new boolean[rows][columns];
        // Initialize all seats as available (false means available)
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < columns; j++) {
                seats[i][j] = false;
            }
        }
    }

    public int getNumberOfSeats() {
        return rows * columns;
    }

    public boolean reserveSeat(int row, int col) {
        // Check if the seat coordinates are valid (1-based indexing)
        if (row < 1 || row > rows || col < 1 || col > columns) {
            throw new IllegalArgumentException("Invalid seat coordinates");
        }

        // Convert to 0-based indexing
        int rowIndex = row - 1;
        int colIndex = col - 1;

        // Check if seat is already reserved
        if (seats[rowIndex][colIndex]) {
            return false; // Already reserved
        }

        // Reserve the seat
        seats[rowIndex][colIndex] = true;
        return true; // Successfully reserved
    }
}

