public class Venue {
    private int rows;
    private int columns;
    private boolean[][] seats;

    public Venue(int rows, int columns) {
        this.rows = rows;
        this.columns = columns;
        this.seats = new boolean[rows][columns];
        // Initialize all seats as available (false means available)
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < columns; j++) {
                seats[i][j] = false;
            }
        }
    }

    public int getNumberOfSeats() {
        return rows * columns;
    }

    public boolean reserveSeat(int row, int col) {
        // Check if the seat coordinates are valid (1-based indexing)
        if (row < 1 || row > rows || col < 1 || col > columns) {
            throw new IllegalArgumentException("Invalid seat coordinates");
        }

        // Convert to 0-based indexing
        int rowIndex = row - 1;
        int colIndex = col - 1;

        // Check if seat is already reserved
        if (seats[rowIndex][colIndex]) {
            return false; // Already reserved
        }

        // Reserve the seat
        seats[rowIndex][colIndex] = true;
        return true; // Successfully reserved
    }

    public int getAvailableSeats() {
        int availableCount = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < columns; j++) {
                if (!seats[i][j]) {
                    availableCount++;
                }
            }
        }
        return availableCount;
    }

    public int[] getBestAvailableSeat() {
        // Check if any seats are available
        if (getAvailableSeats() == 0) {
            return null;
        }

        // Find the best available seat
        int centerCol = columns / 2;

        for (int i = 0; i < rows; i++) {
            // Check center seat first
            if (columns > 0 && !seats[i][centerCol]) {
                return new int[]{i + 1, centerCol + 1}; // Convert to 1-based indexing
            }

            // Check alternating left and right from center
            for (int offset = 1; offset <= columns / 2; offset++) {
                // Check left side
                int leftCol = centerCol - offset;
                if (leftCol >= 0 && !seats[i][leftCol]) {
                    return new int[]{i + 1, leftCol + 1}; // Convert to 1-based indexing
                }

                // Check right side
                int rightCol = centerCol + offset;
                if (rightCol < columns && !seats[i][rightCol]) {
                    return new int[]{i + 1, rightCol + 1}; // Convert to 1-based indexing
                }
            }
        }

        return null; // No available seats found
    }
}

