        // Return success result with metadata
        return new ProcessingResult(Status.SUCCESS, "Message posted to " + destination, metadata);
    }

    public synchronized Message getMessage(String destination) {
        List<Message> messages = destinationMessages.get(destination);
        if (messages == null || messages.isEmpty()) {
            return null;
        }
        return messages.get(messages.size() - 1);
    }

    public synchronized Map<String, Message> getMessagesByType(String contentType) {
        Map<String, Message> result = new LinkedHashMap<>();

        for (Map.Entry<String, List<Message>> entry : destinationMessages.entrySet()) {
            String destination = entry.getKey();
            List<Message> messages = entry.getValue();

            for (Message message : messages) {
                if (message.getContent().contains(contentType)) {
                    result.put(destination, message);
                    break; // Only one message per destination
                }
            }
        }

        return result;
    }

    public synchronized ProcessingResult clearMessages(String destination) {
        List<Message> messages = destinationMessages.get(destination);
        if (messages == null || messages.isEmpty()) {
            return new ProcessingResult(Status.FAILURE, "No messages found for destination: " + destination);
        }

        // Remove messages from the main list
        storedMessages.removeAll(messages);

        // Clear messages for this destination
        messages.clear();

        // Remove from destination counts
        destinationCounts.remove(destination);

        return new ProcessingResult(Status.SUCCESS, "Messages cleared for destination: " + destination);
    }

    // Helper method to get stored messages (optional, for testing purposes)
    public synchronized List<Message> getStoredMessages() {
        return new ArrayList<>(storedMessages);
    }

    // Helper method to get destination counts (optional, for testing purposes)
    public synchronized Map<String, Integer> getDestinationCounts() {
        return new HashMap<>(destinationCounts);
    }

    // Helper method to get destination messages (optional, for testing purposes)
    public synchronized Map<String, List<Message>> getDestinationMessages() {
        return new HashMap<>(destinationMessages);
    }
}
