            result.put("type", obj.getClass().getSimpleName());
            result.put("value", obj);
        } else {
            result.put("type", obj.getClass().getSimpleName());
            result.put("value", obj);
            result.put("fields", inspectFields(obj, maxDepth - 1));
        }

        return result;
