import java.util.ArrayList;
import java.util.Collections;

class CargoOptimizer {

    public static int calculateMaxTrips(ArrayList<Integer> weights, int capacity) {
        if (weights == null || weights.isEmpty()) {
            return 0;
        }

        // Create a copy to avoid modifying the original list
        ArrayList<Integer> remainingWeights = new ArrayList<>(weights);

        // Sort in descending order to process heaviest items first
        Collections.sort(remainingWeights, Collections.reverseOrder());

        int trips = 0;
        int i = 0;

        // First pass: Process items that can travel alone
        while (i < remainingWeights.size()) {
            if (remainingWeights.get(i) >= capacity) {
                trips++;
                remainingWeights.remove(i);
                // Don't increment i since we removed an element
            } else {
                i++;
            }
        }

        // Second pass: Process groups
        while (!remainingWeights.isEmpty()) {
            // Try to form the best possible group starting with the heaviest item
            int heaviest = remainingWeights.get(0);
            int groupSize = 1;

            // Check if this single item qualifies for a group trip
            if (heaviest * groupSize >= capacity) {
                trips++;
                remainingWeights.remove(0);
                continue;
            }

            // Try to add more items to the group
            boolean groupFormed = false;
            for (int j = 1; j < remainingWeights.size(); j++) {
                groupSize = j + 1;
                // Check if the group qualifies (heaviest item * group size >= capacity)
                if (heaviest * groupSize >= capacity) {
                    trips++;
                    // Remove all items in this group
                    for (int k = 0; k < groupSize; k++) {
                        remainingWeights.remove(0);
                    }
                    groupFormed = true;
                    break;
                }
            }

            // If no group could be formed, check if the heaviest item alone qualifies
            if (!groupFormed) {
                if (heaviest * remainingWeights.size() >= capacity && remainingWeights.size() > 0) {
                    trips++;
                    remainingWeights.clear();
                } else {
                    // No more valid trips can be made
                    break;
                }
            }
        }

        return trips;
    }
}

