class CargoOptimizer {

    public static int calculateMaxTrips(ArrayList<Integer> weights, int capacity) {
        // Handle edge cases
        if (weights == null || weights.isEmpty() || capacity <= 0) {
            return 0;
        }

        // Create a copy to avoid modifying the original list
        ArrayList<Integer> workingWeights = new ArrayList<>(weights);

        // Sort in descending order to process heaviest items first
        Collections.sort(workingWeights, Collections.reverseOrder());

        int trips = 0;

        // First pass: Process items that can travel alone (weight >= capacity)
        int i = 0;
        while (i < workingWeights.size()) {
            if (workingWeights.get(i) >= capacity) {
                trips++;
                workingWeights.remove(i);
                // Don't increment i since we removed an element
            } else {
                i++;
            }
        }

        // Second pass: Process groups
        while (!workingWeights.isEmpty()) {
            int heaviest = workingWeights.get(0);
            int groupSize = workingWeights.size();

            // Check if we can form a valid group
            if (heaviest * groupSize >= capacity) {
                trips++;
                break; // All remaining items form one group
            } else {
                // Remove the heaviest item (it cannot form a valid group)
                workingWeights.remove(0);
                // Continue with remaining items
            }
        }

        return trips;
    }
