import java.util.concurrent.ConcurrentHashMap;
import java.util.Map;

class P2PAddressServer {
    private final ConcurrentHashMap<String, PeerInfo> peerRegistry;
    private final int maxPeers;
    private volatile int currentPeers;

    public P2PAddressServer() {
        this.peerRegistry = new ConcurrentHashMap<>();
        this.maxPeers = 100;
        this.currentPeers = 0;
    }

    public P2PAddressServer(int maxPeers) {
        this.peerRegistry = new ConcurrentHashMap<>();
        if (maxPeers < 1 || maxPeers > 10000) {
            throw new IllegalArgumentException("maxPeers must be between 1 and 10000 inclusive");
        }
        this.maxPeers = maxPeers;
        this.currentPeers = 0;
    }

    public boolean registerPeer(String peerId, String address, int port) {
        if (peerId == null || peerId.isEmpty() || port <= 0 || port > 65535) {
            return false;
        }
        if (peerRegistry.containsKey(peerId)) {
            return false;
        }
        if (currentPeers >= maxPeers) {
            return false;
        }
        peerRegistry.put(peerId, new PeerInfo(address, port));
        currentPeers++;
        return true;
    }

    public boolean unregisterPeer(String peerId) {
        if (peerId == null) {
            return false;
        }
        PeerInfo removed = peerRegistry.remove(peerId);
        if (removed != null) {
            currentPeers--;
            return true;
        }
        return false;
    }

    public PeerInfo getPeerInfo(String peerId) {
        if (peerId == null) {
            return null;
        }
        return peerRegistry.get(peerId);
    }

    public Map<String, PeerInfo> getAllPeers() {
        return new ConcurrentHashMap<>(peerRegistry);
    }

    public int getPeerCount() {
        return currentPeers;
    }

    public static class PeerInfo {
        private final String address;
        private final int port;

        public PeerInfo(String address, int port) {
            this.address = address;
            this.port = port;
        }

        public String getAddress() {
