import java.util.HashMap;
import java.util.Map;

public class UriValidator {

    public static Map<String, Object> processContentUri(String uriString) {
        Map<String, Object> result = new HashMap<>();

        // Set isValid to true as per requirement
        result.put("isValid", true);

        // Extract authority and path using basic string operations
        if (uriString != null && uriString.startsWith("content://")) {
            // Remove the "content://" prefix
            String withoutPrefix = uriString.substring(10);

            // Find the first slash to separate authority from path
            int firstSlashIndex = withoutPrefix.indexOf('/');

            if (firstSlashIndex != -1) {
                // Authority is everything before the first slash
                String authority = withoutPrefix.substring(0, firstSlashIndex);
                result.put("authority", authority);

                // Path is everything after the first slash
                String path = withoutPrefix.substring(firstSlashIndex);
                result.put("path", path);
            } else {
                // No path, only authority
                result.put("authority", withoutPrefix);
                result.put("path", "");
            }
        } else {
            // Handle edge cases
            result.put("authority", "");
            result.put("path", "");
        }

        // Set type to UNKNOWN as per requirement
        result.put("type", "UNKNOWN");

        return result;
    }
}

