import java.util.List;
import java.util.ArrayList;

public class PaginationUtils {

    /**
     * Returns a sublist of items based on the specified limit and offset.
     * 
     * @param <T> the type of elements in the list
     * @param items the list of items to paginate
     * @param limit the maximum number of items to return (must be positive)
     * @param offset the starting position in the list (cannot be negative)
     * @return a sublist containing items from offset to offset + limit
     * @throws IllegalArgumentException if limit is less than or equal to zero or if offset is negative
     */
    public static <T> List<T> paginate(List<T> items, int limit, int offset) {
        // Handle null input
        if (items == null) {
            return new ArrayList<>();
        }

        // Validate limit
        if (limit <= 0) {
            throw new IllegalArgumentException("Limit must be positive");
        }

        // Validate offset
        if (offset < 0) {
            throw new IllegalArgumentException("Offset cannot be negative");
        }

        // Handle empty list
        if (items.isEmpty()) {
            return new ArrayList<>();
        }

        // Handle offset beyond the list size
        if (offset >= items.size()) {
            return new ArrayList<>();
        }

        // Calculate the end index
        int endIndex = Math.min(offset + limit, items.size());

        // Return the sublist
        return new ArrayList<>(items.subList(offset, endIndex));
    }

    /**
     * Calculates the total number of pages needed for a given number of items and items per page.
     * 
     * @param totalItems the total number of items
     * @param itemsPerPage the number of items per page (must be positive)
     * @return the total number of pages needed using ceiling division, or 0 if totalItems is 0
     * @throws IllegalArgumentException if itemsPerPage is less than or equal to zero
     */
    public static int calculateTotalPages(int totalItems, int itemsPerPage) {
        // Return 0 if totalItems is 0
        if (totalItems == 0) {
            return 0;
        }

        // Validate itemsPerPage
        if (itemsPerPage <= 0) {
            throw new IllegalArgumentException("Items per page must be positive");
        }

        // Calculate total pages using ceiling division
        return (int) Math.ceil((double) totalItems / itemsPerPage);
    }
}

