import java.util.List;
import java.util.ArrayList;

public class PaginationService<T> {

    public static class PaginatedResult<T> {
        private List<T> items;
        private int total;

        public PaginatedResult(List<T> items, int total) {
            this.items = items;
            this.total = total;
        }

        public List<T> getItems() {
            return items;
        }

        public int getTotal() {
            return total;
        }
    }

    public PaginatedResult<T> paginate(List<T> items, int page, int rowsPerPage) {
        if (items == null) {
            items = new ArrayList<>();
        }

        int total = items.size();

        // Handle edge cases
        if (page < 1 || rowsPerPage <= 0) {
            return new PaginatedResult<>(new ArrayList<>(), total);
        }

        // Calculate start and end indices
        int startIndex = (page - 1) * rowsPerPage;
        int endIndex = Math.min(startIndex + rowsPerPage, total);

        // Handle case where start index is beyond the list size
        if (startIndex >= total) {
            return new PaginatedResult<>(new ArrayList<>(), total);
        }

        // Extract the page items
        List<T> pageItems = new ArrayList<>(items.subList(startIndex, endIndex));

        return new PaginatedResult<>(pageItems, total);
    }
}

