    public PaginatedResult<T> paginate(List<T> items, int page, int rowsPerPage, String key) {
        if (items == null) {
            items = new ArrayList<>();
        }

        // Apply filtering if key is provided
        List<T> filteredItems = items;
        if (key != null && !key.trim().isEmpty()) {
            filteredItems = filterItems(items, key);
        }

        int total = filteredItems.size();

        // Handle edge cases
        if (page < 1 || rowsPerPage <= 0) {
            return new PaginatedResult<>(new ArrayList<>(), total);
        }

        // Calculate start and end indices
        int startIndex = (page - 1) * rowsPerPage;
        int endIndex = Math.min(startIndex + rowsPerPage, total);

        // Handle case where start index is beyond the list size
        if (startIndex >= total) {
            return new PaginatedResult<>(new ArrayList<>(), total);
        }

        // Extract the page items
        List<T> pageItems = new ArrayList<>(filteredItems.subList(startIndex, endIndex));

        return new PaginatedResult<>(pageItems, total);
    }

    private List<T> filterItems(List<T> items, String key) {
        List<T> filtered = new ArrayList<>();
        String lowerCaseKey = key.toLowerCase();

        for (T item : items) {
            if (item != null && item.toString().toLowerCase().contains(lowerCaseKey)) {
                filtered.add(item);
            }
        }

        return filtered;
    }
}

