import java.util.HashMap;
import java.util.Collections;
import java.util.List;
import java.util.ArrayList;
import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class AdvancedFileProcessor {
    private Path directoryPath;

    public AdvancedFileProcessor(String directoryPath) {
        this.directoryPath = Paths.get(directoryPath);

        if (!Files.isDirectory(this.directoryPath)) {
            throw new IllegalArgumentException("Provided path is not a directory: " + directoryPath);
        }
    }

    public Map<String, Object> processFiles() {
        Map<String, Object> statistics = new HashMap<>();

        int fileCount = 0;
        long totalSize = 0;
        String largestFile = "N/A";
        long largestFileSize = -1;
        Map<String, Integer> wordFrequency = new HashMap<>();

        try (DirectoryStream<Path> stream = Files.newDirectoryStream(directoryPath)) {
            for (Path path : stream) {
                if (Files.isRegularFile(path)) {
                    fileCount++;
                    long fileSize = Files.size(path);
                    totalSize += fileSize;

                    if (fileSize > largestFileSize) {
                        largestFileSize = fileSize;
                        largestFile = path.getFileName().toString();
                    }

                    processFileContent(path, wordFrequency);
                }
            }
        } catch (IOException e) {
            // Handle exception - in this case we'll return zero values
            fileCount = 0;
            totalSize = 0;
            largestFile = "N/A";
        }

        statistics.put("fileCount", fileCount);
        statistics.put("totalSize", totalSize);
        statistics.put("largestFile", largestFile);
        statistics.put("wordFrequency", wordFrequency);

        return statistics;
    }

    private void processFileContent(Path file, Map<String, Integer> wordFrequency) {
        try {
            List<String> lines = Files.readAllLines(file);
            for (String line : lines) {
                // Split the line into words using whitespace as delimiter
                String[] words = line.split("\\s+");
                for (String word : words) {
                    // Convert to lowercase
                    String lowerWord = word.toLowerCase();
                    // Remove non-alphabetic characters
                    String cleanedWord = lowerWord.replaceAll("[^a-z]", "");
                    // Ignore empty strings
                    if (!cleanedWord.isEmpty()) {
                        // Update word frequency map
                        wordFrequency.put(cleanedWord, wordFrequency.getOrDefault(cleanedWord, 0) + 1);
                    }
                }
            }
        } catch (IOException e) {
            // Silently ignore files that cannot be read
        }
    }
}

