        for (PhoneContact contact : contacts) {
            if (contact != null && isValidContact(contact)) {
                String formattedPhone = formatPhoneNumber(contact.getPhoneNumber());
                UserInfo userInfo = new UserInfo(contact.getName(), formattedPhone, contact.getEmail());
                processedUsers.add(userInfo);
            }
        }

        Map<String, List<UserInfo>> result = new HashMap<>();
        result.put("processed", processedUsers);
        return result;
    }

    private boolean isValidContact(PhoneContact contact) {
        return contact.getName() != null && !contact.getName().trim().isEmpty() &&
               contact.getPhoneNumber() != null && !contact.getPhoneNumber().trim().isEmpty() &&
               contact.getEmail() != null && contact.getEmail().contains("@");
    }

    private String formatPhoneNumber(String phoneNumber) {
