import java.util.HashMap;

public class UserSettingsManager {
    private final Map<String, Map<String, Object>> userSettings;

    public UserSettingsManager() {
        this.userSettings = new ConcurrentHashMap<>();
    }

    public void saveUserSetting(String key, Object value, String username) {
        if (value == null) {
            throw new IllegalArgumentException("Value cannot be null");
        }

        if (!(value instanceof String || value instanceof Integer || value instanceof Boolean)) {
            throw new IllegalArgumentException("Unsupported value type: " + value.getClass().getSimpleName());
        }

        userSettings.computeIfAbsent(username, k -> new ConcurrentHashMap<>()).put(key, value);
    }

    public <T> T getUserSetting(String key, String username, Class<T> type) {
        Map<String, Object> userMap = userSettings.get(username);
        if (userMap == null) {
            return null;
        }

        Object value = userMap.get(key);
        if (value == null) {
            return null;
        }

        if (!type.isInstance(value)) {
            throw new ClassCastException("Cannot cast " + value.getClass().getSimpleName() + " to " + type.getSimpleName());
        }

        return type.cast(value);
    }

    public void updateUserSettings(Map<String, Object> settings, String username) {
        if (settings == null) {
            return;
        }

        Map<String, Object> validSettings = new ConcurrentHashMap<>();
        for (Map.Entry<String, Object> entry : settings.entrySet()) {
            Object value = entry.getValue();
            if (value != null && (value instanceof String || value instanceof Integer || value instanceof Boolean)) {
                validSettings.put(entry.getKey(), value);
            }
        }

        if (!validSettings.isEmpty()) {
            userSettings.computeIfAbsent(username, k -> new ConcurrentHashMap<>()).putAll(validSettings);
        }
    }

    public Map<String, Object> getAllUserSettings(String username) {
        Map<String, Object> userMap = userSettings.get(username);
        if (userMap == null) {
            return new HashMap<>();
        }

        return new HashMap<>(userMap);
    }

    public Object deleteUserSetting(String key, String username) {
        Map<String, Object> userMap = userSettings.get(username);
        if (userMap == null) {
            return null;
        }

        return userMap.remove(key);
    }

    public void clearUserSettings(String username) {
        Map<String, Object> userMap = userSettings.get(username);
        if (userMap != null) {
            userMap.clear();
        }
    }
}
