public class LinkedList<D> {
    private Node<D> head;
    private Node<D> tail;
    private int size;

    public LinkedList() {
        this.head = null;
        this.tail = null;
        this.size = 0;
    }

    public void add(D data) {
        Node<D> newNode = new Node<>(data);

        if (head == null) {
            // List is empty
            head = newNode;
            tail = newNode;
        } else {
            // List is not empty
            newNode.setPrev(tail);
            tail.setNext(newNode);
            tail = newNode;
        }

        size++;
    }

    public int size() {
        return size;
    }

    private static class Node<D> {
        private D data;
        private Node<D> next;
        private Node<D> prev;

        public Node(D data) {
            this.data = data;
            this.next = null;
            this.prev = null;
        }

        public D getData() {
            return data;
        }

        public Node<D> getNext() {
            return next;
        }

        public Node<D> getPrev() {
            return prev;
        }

        public void setNext(Node<D> next) {
            this.next = next;
        }

        public void setPrev(Node<D> prev) {
            this.prev = prev;
        }
    }
}

