    private Node<D> head;
    private Node<D> tail;
    private int size;

    public LinkedList() {
        this.head = null;
        this.tail = null;
        this.size = 0;
    }

    public void add(D data) {
        Node<D> newNode = new Node<>(data);

        if (head == null) {
            // List is empty
            head = newNode;
            tail = newNode;
        } else {
            // List is not empty
            newNode.setPrev(tail);
            tail.setNext(newNode);
            tail = newNode;
        }

        size++;
    }

    public D get(int index) {
        Node<D> node = getNode(index);
        return node.getData();
    }

    private Node<D> getNode(int index) {
        if (index < 0 || index >= size) {
            throw new IndexOutOfBoundsException("Index: " + index + ", Size: " + size);
        }

        Node<D> current;
        if (index < size / 2) {
            // Traverse from head
            current = head;
            for (int i = 0; i < index; i++) {
                current = current.getNext();
            }
        } else {
            // Traverse from tail
            current = tail;
            for (int i = size - 1; i > index; i--) {
                current = current.getPrev();
            }
        }

        return current;
    }

    public int size() {
        return size;
    }

