class ClientManager {
    private final Map<Long, ClientTO> clients = new ConcurrentHashMap<>();
    private final AtomicLong idGenerator = new AtomicLong(1);

    /**
     * Creates a new client with a unique ID
     * @param clientTO the client data transfer object
     * @return the created client with assigned ID
     * @throws IllegalArgumentException if client is null, has a non-null ID, or if firstName, lastName, or email are null or empty, or email doesn't contain '@'
     */
    public ClientTO createClient(ClientTO clientTO) {
        // Validate client is not null
        if (clientTO == null) {
            throw new IllegalArgumentException("Client cannot be null");
        }

        // Validate ID is null (new client shouldn't have an ID yet)
        if (clientTO.getId() != null) {
            throw new IllegalArgumentException("Client ID must be null for new clients");
        }

        // Validate firstName
        if (clientTO.getFirstName() == null || clientTO.getFirstName().trim().isEmpty()) {
            throw new IllegalArgumentException("First name cannot be null or empty");
        }

        // Validate lastName
        if (clientTO.getLastName() == null || clientTO.getLastName().trim().isEmpty()) {
            throw new IllegalArgumentException("Last name cannot be null or empty");
        }

        // Validate email
        if (clientTO.getEmail() == null || clientTO.getEmail().trim().isEmpty()) {
            throw new IllegalArgumentException("Email cannot be null or empty");
        }

        // Validate email contains '@'
        if (!clientTO.getEmail().contains("@")) {
            throw new IllegalArgumentException("Email must contain '@'");
        }

        // Generate unique ID
        Long newId = idGenerator.getAndIncrement();

        // Create new client with assigned ID
        ClientTO newClient = new ClientTO(
            newId,
            clientTO.getFirstName(),
            clientTO.getLastName(),
            clientTO.getEmail(),
            clientTO.getPhone()
        );

        // Store the client
        clients.put(newId, newClient);

        return newClient;
    }

    /**
     * Finds a client by ID
     * @param id the client ID
     * @param requireAdmin whether admin privileges are required
     * @return the client if found, or null otherwise
     * @throws IllegalArgumentException if the id is null
     * @throws SecurityException if admin privileges are required but not available
     */
    public ClientTO findClient(Long id, boolean requireAdmin) {
        if (requireAdmin && !hasAdminPrivileges()) {
            throw new SecurityException("Admin privileges required to find client");
        }

        if (id == null) {
            throw new IllegalArgumentException("ID cannot be null");
        }
        return clients.get(id);
    }

    /**
     * Updates an existing client after validating its attributes
     * @param clientTO the client data transfer object with updated information
     * @return the updated client
     * @throws IllegalArgumentException if the client is null, does not exist, or has invalid attributes
     */
    public ClientTO updateClient(ClientTO clientTO) {
        // Validate client is not null
        if (clientTO == null) {
            throw new IllegalArgumentException("Client cannot be null");
        }

        // Validate client ID is not null
        if (clientTO.getId() == null) {
            throw new IllegalArgumentException("Client ID cannot be null for update");
        }

        // Validate client exists
        if (!clients.containsKey(clientTO.getId())) {
            throw new IllegalArgumentException("Client with ID " + clientTO.getId() + " does not exist");
        }

        // Validate firstName
        if (clientTO.getFirstName() == null || clientTO.getFirstName().trim().isEmpty()) {
            throw new IllegalArgumentException("First name cannot be null or empty");
        }

        // Validate lastName
        if (clientTO.getLastName() == null || clientTO.getLastName().trim().isEmpty()) {
            throw new IllegalArgumentException("Last name cannot be null or empty");
        }

        // Validate email
        if (clientTO.getEmail() == null || clientTO.getEmail().trim().isEmpty()) {
            throw new IllegalArgumentException("Email cannot be null or empty");
        }

        // Validate email contains '@'
        if (!clientTO.getEmail().contains("@")) {
            throw new IllegalArgumentException("Email must contain '@'");
        }

        // Create updated client
        ClientTO updatedClient = new ClientTO(
            clientTO.getId(),
            clientTO.getFirstName(),
            clientTO.getLastName(),
            clientTO.getEmail(),
            clientTO.getPhone()
        );

        // Update the client
        clients.put(clientTO.getId(), updatedClient);

        return updatedClient;
    }

    /**
     * Deletes a client by ID
     * @param id the client ID
     * @param requireAdmin whether admin privileges are required
     * @return true if deleted, false if not found
     * @throws IllegalArgumentException if the ID is null
     * @throws SecurityException if admin privileges are required but not available
     */
    public boolean deleteClient(Long id, boolean requireAdmin) {
        if (requireAdmin && !hasAdminPrivileges()) {
            throw new SecurityException("Admin privileges required to delete client");
        }

        // Validate ID is not null
        if (id == null) {
            throw new IllegalArgumentException("ID cannot be null");
        }

        // Remove the client and return whether it existed
        return clients.remove(id) != null;
    }

    /**
     * Gets all clients with optional filtering
     * @param filter the filter string (can be null or empty)
     * @param requireAdmin whether admin privileges are required
     * @return a collection of clients matching the filter, or all clients if filter is null/empty
     * @throws SecurityException if admin privileges are required but not available
     */
    public Collection<ClientTO> findAllClients(String filter, boolean requireAdmin) {
        if (requireAdmin && !hasAdminPrivileges()) {
            throw new SecurityException("Admin privileges required to find all clients");
        }

        // If filter is null or empty, return all clients
        if (filter == null || filter.trim().isEmpty()) {
            return new ArrayList<>(clients.values());
        }

        // Filter clients by first name, last name, or email (case insensitive)
        String lowerCaseFilter = filter.toLowerCase().trim();
        return clients.values().stream()
                .filter(client -> 
                    client.getFirstName().toLowerCase().contains(lowerCaseFilter) ||
                    client.getLastName().toLowerCase().contains(lowerCaseFilter) ||
                    client.getEmail().toLowerCase().contains(lowerCaseFilter))
                .collect(Collectors.toList());
    }

    /**
     * Finds clients by first name or last name
     * @param name the name to search for
     * @param requireAdmin whether admin privileges are required
     * @return a collection of clients matching the name
     * @throws IllegalArgumentException if the name is null or empty
     * @throws SecurityException if admin privileges are required but not available
     */
    public Collection<ClientTO> findClientsByName(String name, boolean requireAdmin) {
        if (requireAdmin && !hasAdminPrivileges()) {
            throw new SecurityException("Admin privileges required to find clients by name");
        }

        // Validate name is not null or empty
        if (name == null || name.trim().isEmpty()) {
            throw new IllegalArgumentException("Name cannot be null or empty");
        }

        String lowerCaseName = name.toLowerCase().trim();
        return clients.values().stream()
                .filter(client -> 
                    client.getFirstName().toLowerCase().contains(lowerCaseName) ||
                    client.getLastName().toLowerCase().contains(lowerCaseName))
                .collect(Collectors.toList());
    }

    /**
     * Checks if the current user has admin privileges
     * @return false always (as specified in the requirements)
     */
    public boolean hasAdminPrivileges() {
        return false;
    }

    /**
     * Gets the number of clients
     * @return the client count
     */
    public int getClientCount() {
        return clients.size();
    }
}
