        // Filter tasks based on criteria
        List<Map<String, Object>> filteredTasks = new ArrayList<>();

        for (Map<String, Object> task : taskCache) {
            boolean matches = true;

            for (Map.Entry<String, Object> entry : criteria.entrySet()) {
                String key = entry.getKey();
                Object value = entry.getValue();

                if (!task.containsKey(key) || !task.get(key).equals(value)) {
                    matches = false;
                    break;
                }
            }

            if (matches) {
                filteredTasks.add(task);
            }
        }

        // Calculate pagination
        int totalItems = filteredTasks.size();
        int totalPages = (int) Math.ceil((double) totalItems / pageSize);

        // Clamp page to valid range
        if (totalPages == 0) {
            page = 1;
        } else {
            if (page < 1) {
                page = 1;
            } else if (page > totalPages) {
                page = totalPages;
            }
        }

        // Extract page data
        List<Map<String, Object>> paginatedTasks = new ArrayList<>();
        if (totalItems > 0) {
            int startIndex = (page - 1) * pageSize;
            int endIndex = Math.min(startIndex + pageSize, totalItems);
            paginatedTasks = filteredTasks.subList(startIndex, endIndex);
        }

        // Prepare response
        Map<String, Object> response = new HashMap<>();
        response.put("tasks", paginatedTasks);
        response.put("currentPage", page);
        response.put("totalPages", totalPages > 0 ? totalPages : 1);
        response.put("totalItems", totalItems);

        return response;
    }

    public Map<String, Object> updateTaskStats(String taskId, int successIncrement, int failIncrement, int scoreIncrement) {
        // Find the task with the specified taskId
        Map<String, Object> task = null;
        for (Map<String, Object> t : taskCache) {
            if (taskId.equals(t.get("taskId"))) {
                task = t;
                break;
            }
        }

        // If task not found, return error
        if (task == null) {
            Map<String, Object> response = new HashMap<>();
            response.put("status", "error");
            response.put("message", "Task not found");
            return response;
        }

        // Update the stats
        List<String> modifiedFields = new ArrayList<>();

        int oldSuccessCount = (Integer) task.get("successCount");
        int newSuccessCount = oldSuccessCount + successIncrement;
        task.put("successCount", newSuccessCount);
        modifiedFields.add("successCount");

        int oldFailCount = (Integer) task.get("failCount");
        int newFailCount = oldFailCount + failIncrement;
        task.put("failCount", newFailCount);
        modifiedFields.add("failCount");

        int oldScore = (Integer) task.get("score");
        int newScore = oldScore + scoreIncrement;
        task.put("score", newScore);
        modifiedFields.add("score");

        // Update status if successCount > 0
        String oldStatus = (String) task.get("status");
        if (newSuccessCount > 0 && !"completed".equals(oldStatus)) {
            task.put("status", "completed");
            modifiedFields.add("status");
        }

        // Prepare response
        Map<String, Object> response = new HashMap<>();
        response.put("status", "success");
        response.put("modifiedFields", modifiedFields);

        return response;
    }
}
