class BudgetVersionManager {
    public List<String> validateBudgetVersion(VersaoOrcamento version) {
        List<String> errors = new ArrayList<>();
        if (version == null) {
            errors.add("Budget version cannot be null");
        } else {
            if (version.getIdVersaoOrcamento() == null) {
                errors.add("Version ID cannot be null");
            }

            if (version.getDescricaoMensagem() == null || version.getDescricaoMensagem().trim().isEmpty()) {
                errors.add("Description message is required");
            }

            String status = version.getIdtStatus();
            if (status == null || (!status.equals("A") && !status.equals("R") && !status.equals("P"))) {
                errors.add("Status must be one of: A, R, P");
            }

            if (version.getDataVigencia() == null) {
                errors.add("Effective date is required");
            }
        }
        return errors;
    }

    public List<VersaoOrcamento> filterVersions(List<VersaoOrcamento> versions, String status, Timestamp fromDate, Timestamp toDate) {
        if (versions == null) {
            return new ArrayList<>();
        }

        List<VersaoOrcamento> filtered = new ArrayList<>();

        for (VersaoOrcamento version : versions) {
            if (version == null) {
                continue;
            }

            // Filter by status if provided
            if (status != null && !status.equals(version.getIdtStatus())) {
                continue;
            }

            // Filter by date range if provided
            if (fromDate != null && (version.getDataVigencia() == null || version.getDataVigencia().before(fromDate))) {
                continue;
            }

            if (toDate != null && (version.getDataVigencia() == null || version.getDataVigencia().after(toDate))) {
                continue;
            }

            filtered.add(version);
        }

        return filtered;
    }

    public BudgetVersionAnalysis analyzeVersions(List<VersaoOrcamento> versions) {
        BudgetVersionAnalysis analysis = new BudgetVersionAnalysis();

        if (versions == null || versions.isEmpty()) {
            return analysis;
        }

        int approvedCount = 0;
        int rejectedCount = 0;
        int pendingCount = 0;
        Timestamp earliestDate = null;
        Timestamp latestDate = null;

        for (VersaoOrcamento version : versions) {
            if (version == null) {
                continue;
            }

            // Count by status
            String status = version.getIdtStatus();
            if ("A".equals(status)) {
                approvedCount++;
            } else if ("R".equals(status)) {
                rejectedCount++;
            } else if ("P".equals(status)) {
                pendingCount++;
            }

            // Track earliest and latest dates
            Timestamp vigenciaDate = version.getDataVigencia();
            if (vigenciaDate != null) {
                if (earliestDate == null || vigenciaDate.before(earliestDate)) {
                    earliestDate = vigenciaDate;
                }
                if (latestDate == null || vigenciaDate.after(latestDate)) {
                    latestDate = vigenciaDate;
                }
            }
        }

        analysis.setTotalCount(versions.size());
        analysis.setApprovedCount(approvedCount);
        analysis.setRejectedCount(rejectedCount);
        analysis.setPendingCount(pendingCount);
        analysis.setEarliestDate(earliestDate);
        analysis.setLatestDate(latestDate);

        return analysis;
    }
}

