import java.util.regex.Pattern;

public class DocumentationValidator {
    public static final Pattern INVALID_CHAR_PATTERN = Pattern.compile("\\\\");
    public static final Pattern PLACEHOLDER_PATTERN = Pattern.compile("\\$\\{[^}]*\\}");
    public static final List<String> ALLOWED_PLACEHOLDERS = Collections.unmodifiableList(
        Arrays.asList("method", "class", "param", "return")
    );

    public static void validateDocumentation(String doc, String qualifiedName) {
        if (doc == null) {
            return;
        }

        if (doc.trim().isEmpty()) {
            throw new IllegalArgumentException("Empty documentation string for: " + qualifiedName);
        }

        if (doc.length() > 500) {
            throw new IllegalArgumentException("Documentation exceeds 500 characters for: " + qualifiedName);
        }

        if (INVALID_CHAR_PATTERN.matcher(doc).find()) {
            throw new IllegalArgumentException("Documentation contains invalid characters: " + qualifiedName);
        }

        Matcher matcher = PLACEHOLDER_PATTERN.matcher(doc);
        while (matcher.find()) {
            String placeholder = matcher.group();
            String placeholderName = placeholder.substring(2, placeholder.length() - 1);
            if (!ALLOWED_PLACEHOLDERS.contains(placeholderName)) {
                throw new IllegalArgumentException("Invalid placeholder '" + placeholderName + "' in documentation for: " + qualifiedName);
            }
        }
    }

    public static void validateClassDocumentation(String classDoc, String className, String[] methodDocs) {
        validateDocumentation(classDoc, className);

        for (int i = 0; i < methodDocs.length; i++) {
            String methodName = className + ".method" + (i + 1);
            validateDocumentation(methodDocs[i], methodName);
        }
    }
}

