public class AdvancedDotProductCalculator {

    public static int calculateDotProduct(int[] array1, int[] array2) {
        // Check if first array is null
        if (array1 == null) {
            throw new IllegalArgumentException("First array cannot be null");
        }

        // Check if second array is null
        if (array2 == null) {
            throw new IllegalArgumentException("Second array cannot be null");
        }

        // Check if arrays have different lengths
        if (array1.length != array2.length) {
            throw new IllegalArgumentException("Arrays must have the same length");
        }

        // Handle empty arrays
        if (array1.length == 0) {
            return 0;
        }

        // Calculate dot product
        int dotProduct = 0;
        for (int i = 0; i < array1.length; i++) {
            dotProduct += array1[i] * array2[i];
        }

        return dotProduct;
    }

    public static int calculateDotProduct(int[] array1, int[] array2, int threadCount) {
        // Check if first array is null
        if (array1 == null) {
            throw new IllegalArgumentException("First array cannot be null");
        }

        // Check if second array is null
        if (array2 == null) {
            throw new IllegalArgumentException("Second array cannot be null");
        }

        // Check if arrays have different lengths
        if (array1.length != array2.length) {
            throw new IllegalArgumentException("Arrays must have the same length");
        }

        // Handle empty arrays
        if (array1.length == 0) {
            return 0;
        }

        // Validate thread count
        if (threadCount <= 0) {
            throw new IllegalArgumentException("Thread count must be positive");
        }

        // If threadCount is 1 or greater than array length, use sequential calculation
        if (threadCount == 1 || threadCount >= array1.length) {
            return calculateDotProduct(array1, array2);
        }

        // Create thread pool
        ExecutorService executor = Executors.newFixedThreadPool(threadCount);

        try {
            // Divide work into chunks
            int chunkSize = array1.length / threadCount;
            int remainder = array1.length % threadCount;

            List<Future<Integer>> futures = new ArrayList<>();

            int startIndex = 0;
            for (int i = 0; i < threadCount; i++) {
                // Distribute remainder elements among first 'remainder' threads
                int endIndex = startIndex + chunkSize + (i < remainder ? 1 : 0);

                // Create and submit task
                Callable<Integer> task = new DotProductTask(array1, array2, startIndex, endIndex);
                futures.add(executor.submit(task));

                startIndex = endIndex;
            }

            // Collect results and sum them
            int totalDotProduct = 0;
            for (Future<Integer> future : futures) {
                totalDotProduct += future.get();
            }

            return totalDotProduct;
        } catch (Exception e) {
            throw new RuntimeException("Error during parallel computation", e);
        } finally {
            executor.shutdown();
        }
    }

    // Helper class for parallel computation tasks
    private static class DotProductTask implements Callable<Integer> {
        private final int[] array1;
        private final int[] array2;
        private final int startIndex;
        private final int endIndex;

        public DotProductTask(int[] array1, int[] array2, int startIndex, int endIndex) {
            this.array1 = array1;
            this.array2 = array2;
            this.startIndex = startIndex;
            this.endIndex = endIndex;
        }

        @Override
        public Integer call() {
            int partialSum = 0;
            for (int i = startIndex; i < endIndex; i++) {
                partialSum += array1[i] * array2[i];
            }
            return partialSum;
        }
    }
}

