import java.util.HashMap;
import java.util.Map;

class RegionTextureManager {
    private Map<String, TexturePack> regionPacks = new HashMap<>();
    private TexturePack defaultPack;

    public RegionTextureManager(TexturePack defaultPack) {
        this.defaultPack = defaultPack;
    }

    public void addRegionPack(String regionId, TexturePack pack) {
        regionPacks.put(regionId, pack);
    }

    public TexturePack getTexturePack(String regionId) {
        return regionPacks.getOrDefault(regionId, defaultPack);
    }

    public void removeRegionPack(String regionId) {
        regionPacks.remove(regionId);
    }

    public boolean hasCustomPack(String regionId) {
        TexturePack pack = regionPacks.get(regionId);
        return pack != null && pack.isCustom();
    }

    public TexturePack getDefaultPack() {
        return defaultPack;
    }
}

class TexturePack {
    private String name;
    private boolean isCustom;

    public TexturePack(String name, boolean isCustom) {
        this.name = name;
        this.isCustom = isCustom;
    }

    public String getName() {
        return name;
    }

    public boolean isCustom() {
        return isCustom;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        TexturePack that = (TexturePack) obj;
        return isCustom == that.isCustom && name.equals(that.name);
    }

    @Override
    public int hashCode() {
        return name.hashCode() * 31 + (isCustom ? 1 : 0);
    }
}

