import java.util.List;

class MinesweeperSolver {
    private char[][] map;
    private boolean[][] visited;
    private final int[] dirR = {-1, -1, -1, 0, 0, 1, 1, 1};
    private final int[] dirC = {-1, 0, 1, -1, 1, -1, 0, 1};

    public int solveMinesweeper(int boardSize, List<String> minePositions) {
        map = new char[boardSize + 2][boardSize + 2];
        visited = new boolean[boardSize + 2][boardSize + 2];

        // Initialize the board with safe cells
        for (int i = 1; i <= boardSize; i++) {
            for (int j = 1; j <= boardSize; j++) {
                map[i][j] = '.';
            }
        }

        // Place mines at specified positions
        for (String pos : minePositions) {
            String[] parts = pos.split(",");
            int r = Integer.parseInt(parts[0]);
            int c = Integer.parseInt(parts[1]);
            map[r][c] = '*';
        }

        // Calculate adjacent mine counts for each non-mine cell
        for (int i = 1; i <= boardSize; i++) {
            for (int j = 1; j <= boardSize; j++) {
                if (map[i][j] != '*') {
                    int count = 0;
                    for (int d = 0; d < 8; d++) {
                        int nr = i + dirR[d];
                        int nc = j + dirC[d];
                        if (map[nr][nc] == '*') {
                            count++;
                        }
                    }
                    map[i][j] = (char) (count + '0');
                }
            }
        }

        // Simulate clicking on all unvisited safe cells
        int clicks = 0;
        for (int i = 1; i <= boardSize; i++) {
            for (int j = 1; j <= boardSize; j++) {
                if (map[i][j] != '*' && !visited[i][j]) {
                    dfsReveal(i, j);
                    clicks++;
                }
            }
        }

        return clicks;
    }

    private void dfsReveal(int r, int c) {
        // Base cases: out of bounds, already visited, or mine
        if (r < 1 || r >= map.length - 1 || c < 1 || c >= map[0].length - 1 || 
            visited[r][c] || map[r][c] == '*') {
            return;
        }

        // Mark current cell as visited
        visited[r][c] = true;

        // If current cell has adjacent mines, stop recursion
        if (map[r][c] > '0') {
            return;
        }

        // Recursively reveal all 8 neighbors if current cell is '0'
        for (int d = 0; d < 8; d++) {
            dfsReveal(r + dirR[d], c + dirC[d]);
        }
    }
}

