import java.util.ArrayList;
import java.util.List;

class FrequencyAssignment {
    private String name;
    private double requiredBandwidth;

    public FrequencyAssignment(String name, double requiredBandwidth) {
        this.name = name;
        this.requiredBandwidth = requiredBandwidth;
    }

    public String getName() {
        return name;
    }

    public double getRequiredBandwidth() {
        return requiredBandwidth;
    }
}

class Channel {
    private String identifier;
    private double availableBandwidth;

    public Channel(String identifier, double availableBandwidth) {
        this.identifier = identifier;
        this.availableBandwidth = availableBandwidth;
    }

    public String getIdentifier() {
        return identifier;
    }

    public double getAvailableBandwidth() {
        return availableBandwidth;
    }
}

class Plan {
    private List<FrequencyAssignment> assignments;
    private List<Channel> channels;

    public Plan() {
        this.assignments = new ArrayList<>();
        this.channels = new ArrayList<>();
    }

    public void addAssignment(FrequencyAssignment assignment) {
        assignments.add(assignment);
    }

    public void addChannel(Channel channel) {
        channels.add(channel);
    }

    public double getTotalRequiredBandwidth() {
        double total = 0;
        for (FrequencyAssignment assignment : assignments) {
            total += assignment.getRequiredBandwidth();
        }
        return total;
    }

    public double getTotalAvailableBandwidth() {
        double total = 0;
        for (Channel channel : channels) {
            total += channel.getAvailableBandwidth();
        }
        return total;
    }

    public List<FrequencyAssignment> getAssignments() {
        return new ArrayList<>(assignments);
    }

    public List<Channel> getChannels() {
        return new ArrayList<>(channels);
    }
}

public class FrequencyPlanner {

    public static Plan createPlan(double[] requiredBandwidths, String[] assignmentNames, 
                                 double[] availableBandwidths, String[] channelIdentifiers) {
        Plan plan = new Plan();

        // Process assignments - only add valid positive bandwidths
        int assignmentCount = Math.min(requiredBandwidths.length, assignmentNames.length);
        for (int i = 0; i < assignmentCount; i++) {
            if (requiredBandwidths[i] > 0) {
                String name = (i < assignmentNames.length) ? assignmentNames[i] : "Assignment" + i;
                plan.addAssignment(new FrequencyAssignment(name, requiredBandwidths[i]));
            }
        }

        // Process channels - only add valid positive bandwidths
        int channelCount = Math.min(availableBandwidths.length, channelIdentifiers.length);
        for (int i = 0; i < channelCount; i++) {
            if (availableBandwidths[i] > 0) {
                String identifier = (i < channelIdentifiers.length) ? channelIdentifiers[i] : "Channel" + i;
                plan.addChannel(new Channel(identifier, availableBandwidths[i]));
            }
        }

        return plan;
    }
}

