        if (obj == null || getClass() != obj.getClass()) return false;
        Plan plan = (Plan) obj;
        return Objects.equals(assignments, plan.assignments) &&
               Objects.equals(channels, plan.channels);
    }

    @Override
    public int hashCode() {
        return Objects.hash(assignments, channels);
    }
}

public class FrequencyPlanner {

    public static Plan createPlan(double[] requiredBandwidths, String[] assignmentNames, 
                                 double[] availableBandwidths, String[] channelIdentifiers) {
        Plan plan = new Plan();

        // Process assignments - only add valid positive bandwidths
        int assignmentCount = Math.min(requiredBandwidths.length, assignmentNames.length);
        for (int i = 0; i < assignmentCount; i++) {
            if (requiredBandwidths[i] > 0 && assignmentNames[i] != null) {
                String name = assignmentNames[i];
                plan.addAssignment(new FrequencyAssignment(name, requiredBandwidths[i]));
            }
        }

        // Process channels - only add valid positive bandwidths
        int channelCount = Math.min(availableBandwidths.length, channelIdentifiers.length);
        for (int i = 0; i < channelCount; i++) {
            if (availableBandwidths[i] > 0 && channelIdentifiers[i] != null) {
                String identifier = channelIdentifiers[i];
                plan.addChannel(new Channel(identifier, availableBandwidths[i]));
            }
        }

        return plan;
    }
}
