class TaxPriceCalculator {

    public static BigDecimal[] calculatePriceAndTax(BigDecimal totalAmount, BigDecimal taxRate, boolean isTaxIncluded) {
        // Input validation
        if (totalAmount == null) {
            throw new IllegalArgumentException("totalAmount cannot be null");
        }
        if (taxRate == null) {
            throw new IllegalArgumentException("taxRate cannot be null");
        }
        if (totalAmount.compareTo(BigDecimal.ZERO) < 0) {
            throw new IllegalArgumentException("totalAmount cannot be negative");
        }
        if (taxRate.compareTo(BigDecimal.ZERO) < 0) {
            throw new IllegalArgumentException("taxRate cannot be negative");
        }

        BigDecimal[] result = new BigDecimal[2];

        if (isTaxIncluded) {
            // When tax is included in the total amount
            BigDecimal taxRateDecimal = taxRate.divide(BigDecimal.valueOf(100), 10, RoundingMode.HALF_UP);
            BigDecimal divisor = BigDecimal.ONE.add(taxRateDecimal);
            BigDecimal priceAmount = totalAmount.divide(divisor, 10, RoundingMode.HALF_UP);
            BigDecimal taxAmount = totalAmount.subtract(priceAmount);

            result[0] = priceAmount.setScale(2, RoundingMode.HALF_UP);
            result[1] = taxAmount.setScale(2, RoundingMode.HALF_UP);
        } else {
            // When tax is not included in the total amount
            BigDecimal taxRateDecimal = taxRate.divide(BigDecimal.valueOf(100), 10, RoundingMode.HALF_UP);
            BigDecimal taxAmount = totalAmount.multiply(taxRateDecimal).setScale(2, RoundingMode.HALF_UP);
            BigDecimal priceAmount = totalAmount;

            result[0] = priceAmount;
            result[1] = taxAmount;
        }

        return result;
    }
}

