            int nameIndex = categoryObj.indexOf("\"name\":");
            int startQuote = categoryObj.indexOf('"', nameIndex + 7);
            if (startQuote != -1) {
                int endQuote = categoryObj.indexOf('"', startQuote + 1);
                if (endQuote != -1) {
                    return categoryObj.substring(startQuote + 1, endQuote);
                }
            }
            // Check for null value
            if (categoryObj.contains("\"name\":null") || categoryObj.contains("\"name\": null")) {
                return "";
            }
        }
        // Missing name field or invalid format
        return "";
