        int lastIndex = 0;
        boolean inQuotes = false;
        for (int i = 0; i < dataContent.length(); i++) {
            char c = dataContent.charAt(i);
            if (c == '"') {
                inQuotes = !inQuotes;
            } else if (!inQuotes) {
                if (c == '{') {
                    braceCount++;
