        if (lastIndex < dataContent.length()) {
            entries.add(dataContent.substring(lastIndex).trim());
        }
        return entries;
    }

    private static int extractProductQuantity(String productEntry) {
        // Extract key (product name) and value (product object)
        int colonIndex = productEntry.indexOf(':');
        if (colonIndex == -1) {
            return 0;
        }

        String productObj = productEntry.substring(colonIndex + 1).trim();
        if (productObj.startsWith("{") && productObj.endsWith("}")) {
            productObj = productObj.substring(1, productObj.length() - 1);

            // Look for quantity field
            if (productObj.contains("\"quantity\":")) {
                int quantityIndex = productObj.indexOf("\"quantity\":");
                String quantityPart = productObj.substring(quantityIndex + 11).trim();

                // Check for null value
                if (quantityPart.startsWith("null")) {
                    return 0;
                }

                // Extract numeric value
                int commaIndex = quantityPart.indexOf(',');
                if (commaIndex == -1) {
                    commaIndex = quantityPart.length();
                }

                String quantityStr = quantityPart.substring(0, commaIndex).trim();
                try {
                    return Integer.parseInt(quantityStr);
                } catch (NumberFormatException e) {
                    return 0;
                }
            }
            // Missing quantity field
            return 0;
        }
        return 0;
    }

    private static int findMatchingClosingBrace(String str, int openingPos) {
        int counter = 1;
        for (int i = openingPos + 1; i < str.length(); i++) {
            if (str.charAt(i) == '{') {
                counter++;
            } else if (str.charAt(i) == '}') {
