import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;

public class KeyValueStore {
    private final ConcurrentHashMap<String, String> store;
    private final ConcurrentHashMap<String, AtomicLong> accessCounts;
    private final ConcurrentHashMap<String, Long> lastAccessTimes;
    private final ConcurrentHashMap<Class<?>, AtomicLong> typeCounts;

    public KeyValueStore() {
        this.store = new ConcurrentHashMap<>();
        this.accessCounts = new ConcurrentHashMap<>();
        this.lastAccessTimes = new ConcurrentHashMap<>();
        this.typeCounts = new ConcurrentHashMap<>();
    }

    public void put(String key, String value) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }

        // Update type count for the old value if it exists
        String oldValue = store.get(key);
        if (oldValue != null) {
            Class<?> oldType = oldValue.getClass();
            AtomicLong oldCount = typeCounts.get(oldType);
            if (oldCount != null) {
                oldCount.decrementAndGet();
            }
        }

        // Store the new value
        store.put(key, value);

        // Update type count for the new value
        Class<?> newType = value.getClass();
        typeCounts.computeIfAbsent(newType, k -> new AtomicLong(0)).incrementAndGet();

        // Initialize access count for the key
        accessCounts.putIfAbsent(key, new AtomicLong(0));
    }

    public String get(String key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }

        String value = store.get(key);
        if (value != null) {
            accessCounts.computeIfAbsent(key, k -> new AtomicLong(0)).incrementAndGet();
            lastAccessTimes.put(key, System.currentTimeMillis());
        }
        return value;
    }

    public long getAccessCount(String key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }

        AtomicLong count = accessCounts.get(key);
        return count != null ? count.get() : 0;
    }

    public long getLastAccessTime(String key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }

        Long lastAccessTime = lastAccessTimes.get(key);
        return lastAccessTime != null ? lastAccessTime : 0;
    }

    public long getTypeCount(Class<?> type) {
        if (type == null) {
            throw new IllegalArgumentException("Type cannot be null");
        }

        AtomicLong count = typeCounts.get(type);
        return count != null ? count.get() : 0;
    }
}

