import java.util.*;
import java.util.function.*;

class WebSocketMessageHandler {
    private final Map<String, Consumer<Map<String, Object>>> messageHandlers;
    private final BiConsumer<String, String> errorLogger;
    private final RateLimiter rateLimiter;

    public WebSocketMessageHandler(BiConsumer<String, String> errorLogger) {
        this.messageHandlers = new HashMap<>();
        this.errorLogger = errorLogger;
        this.rateLimiter = new RateLimiter(100);
    }

    public void addMessageHandler(String messageType, Consumer<Map<String, Object>> handler) {
        messageHandlers.put(messageType, handler);
    }

    public boolean processMessage(String messageType, Map<String, Object> messageData) {
        // Check rate limit first
        if (!rateLimiter.allowRequest()) {
            return false;
        }

        // Validate message type and data
        if (messageType == null || messageType.isEmpty() || messageData == null) {
            return false;
        }

        Consumer<Map<String, Object>> handler = messageHandlers.get(messageType);
        if (handler != null) {
            try {
                handler.accept(messageData);
                return true;
            } catch (Exception e) {
                if (errorLogger != null) {
                    errorLogger.accept("Error processing message type: " + messageType, e.getMessage());
                }
                return false;
            }
        }
        return false;
    }

    private static class RateLimiter {
        private final int maxRequestsPerSecond;
        private final Queue<Long> requestTimestamps;

        public RateLimiter(int maxRequestsPerSecond) {
            this.maxRequestsPerSecond = maxRequestsPerSecond;
            this.requestTimestamps = new LinkedList<>();
        }

        public boolean allowRequest() {
            long now = System.currentTimeMillis();
            long oneSecondAgo = now - 1000;

            // Remove timestamps older than 1 second
            while (!requestTimestamps.isEmpty() && requestTimestamps.peek() <= oneSecondAgo) {
                requestTimestamps.poll();
            }

            // Check if we can allow another request
            if (requestTimestamps.size() < maxRequestsPerSecond) {
                requestTimestamps.offer(now);
                return true;
            }

            return false;
        }
    }
}

