public class GameOfLifePatterns {

    /**
     * Creates a square boolean 2D array of the given size
     * @param size the size of the square grid
     * @return a new boolean[][] array of size x size
     */
    public static boolean[][] createGrid(int size) {
        return new boolean[size][size];
    }

    /**
     * Counts the number of live cells (true values) in the grid
     * @param grid the boolean 2D array to count live cells in
     * @return the number of true values in the grid
     */
    public static int countLiveCells(boolean[][] grid) {
        if (grid == null) {
            return 0;
        }

        int count = 0;
        for (int i = 0; i < grid.length; i++) {
            if (grid[i] != null) {
                for (int j = 0; j < grid[i].length; j++) {
                    if (grid[i][j]) {
                        count++;
                    }
                }
            }
        }
        return count;
    }
}

