        // Initialize options storage
        this.options = new HashMap<>();

        // Initialize default options
        this.defaultOptions = new HashMap<>();
        this.defaultOptions.put("header_footer", true);
        this.defaultOptions.put("compact", false);
        this.defaultOptions.put("safe", 0);

        // Initialize required options
        this.requiredOptions = new HashSet<>();
        this.requiredOptions.add("backend");
        this.requiredOptions.add("doctype");

        // Initialize option dependencies
        this.optionDependencies = new HashMap<>();
        this.optionDependencies.put("template_engine", "template_dirs");
    }

    public void setOption(String key, Object value) {
        if (value == null) {
            throw new IllegalArgumentException("Option value cannot be null");
        }

        validateOption(key, value);
        this.options.put(key, value);
