import java.util.*;

public class AdditionChainFinder {

    public List<Integer> findShortestAdditionChain(int target) {
        if (target <= 0) {
            return new ArrayList<>();
        }

        if (target == 1) {
            return Arrays.asList(1);
        }

        // BFS to find the shortest addition chain
        Queue<List<Integer>> queue = new LinkedList<>();
        Set<Integer> visited = new HashSet<>();

        // Start with the chain containing just 1
        List<Integer> initialChain = new ArrayList<>();
        initialChain.add(1);
        queue.offer(initialChain);
        visited.add(1);

        while (!queue.isEmpty()) {
            List<Integer> currentChain = queue.poll();
            int lastElement = currentChain.get(currentChain.size() - 1);

            // If we've reached the target, return the chain
            if (lastElement == target) {
                return currentChain;
            }

            // If we've exceeded the target, skip this chain
            if (lastElement > target) {
                continue;
            }

            // Try adding each element in the current chain to the last element
            for (int i = 0; i < currentChain.size(); i++) {
                int nextElement = currentChain.get(i) + lastElement;

                // If we haven't visited this number and it's not greater than target
                if (nextElement <= target && !visited.contains(nextElement)) {
                    List<Integer> newChain = new ArrayList<>(currentChain);
                    newChain.add(nextElement);
                    queue.offer(newChain);
                    visited.add(nextElement);
                }
            }
        }

        // If no chain is found (shouldn't happen for positive integers)
        return new ArrayList<>();
    }
}

