        List<Integer> bestChain = null;
        int minLength = Integer.MAX_VALUE;

        // Start DFS
        List<Integer> currentChain = new ArrayList<>();
        currentChain.add(1);
        Set<Integer> currentSet = new HashSet<>();
        currentSet.add(1);

        // Perform DFS to find the shortest addition chain
        bestChain = dfs(target, currentChain, currentSet, bestChain, minLength);

        return bestChain != null ? bestChain : new ArrayList<>();
    }

    private List<Integer> dfs(int target, List<Integer> currentChain, Set<Integer> currentSet, 
                              List<Integer> bestChain, int minLength) {
        int lastElement = currentChain.get(currentChain.size() - 1);

        // Pruning: if current chain is already longer than or equal to the best found, stop
        if (bestChain != null && currentChain.size() >= bestChain.size()) {
            return bestChain;
        }

        // If we've reached the target, we found a valid chain
        if (lastElement == target) {
            if (bestChain == null || currentChain.size() < bestChain.size() || 
                (currentChain.size() == bestChain.size() && isLexicographicallySmaller(currentChain, bestChain))) {
                return new ArrayList<>(currentChain);
            }
            return bestChain;
        }

        // If we've exceeded the target, this path is invalid
        if (lastElement > target) {
            return bestChain;
        }

        // Try adding each element (including itself) in the current chain to the last element
        // Process in reverse order to potentially find lexicographically smaller solutions faster
        for (int i = currentChain.size() - 1; i >= 0; i--) {
            int nextElement = currentChain.get(i) + lastElement;

            // Skip if next element exceeds target
            if (nextElement > target) {
                continue;
            }

            // Add next element to chain
            currentChain.add(nextElement);
            currentSet.add(nextElement);

            // Recursively explore
            bestChain = dfs(target, currentChain, currentSet, bestChain, minLength);

            // Backtrack
            currentChain.remove(currentChain.size() - 1);
            currentSet.remove(nextElement);
        }

        return bestChain;
    }

    private boolean isLexicographicallySmaller(List<Integer> chain1, List<Integer> chain2) {
        int minSize = Math.min(chain1.size(), chain2.size());
        for (int i = 0; i < minSize; i++) {
            int diff = chain1.get(i).compareTo(chain2.get(i));
            if (diff != 0) {
                return diff < 0;
            }
        }
        return chain1.size() < chain2.size();
    }

    public static boolean validateAdditionChain(List<Integer> chain, int target) {
        // Check if chain is null or empty
        if (chain == null || chain.isEmpty()) {
            return false;
        }

        // Check if chain starts with 1
        if (chain.get(0) != 1) {
            return false;
        }

        // Check if chain ends with target
        if (chain.get(chain.size() - 1) != target) {
            return false;
        }

        // Check each element after the first is sum of two previous elements
        for (int i = 1; i < chain.size(); i++) {
            int current = chain.get(i);
            boolean found = false;

            // Check if current element can be expressed as sum of two previous elements
            for (int j = 0; j < i; j++) {
