        if (cleanedString.isEmpty()) {
            return "";
        }

        String titleCaseString = cleanedString.substring(0, 1).toUpperCase() + 
                                cleanedString.substring(1).toLowerCase();

        // If the resulting string has more than 5 characters, reverse it
        String finalString = titleCaseString;
        if (titleCaseString.length() > 5) {
            finalString = new StringBuilder(titleCaseString).reverse().toString();
        }

        // Apply length-based markers
        if (finalString.isEmpty()) {
            return "Empty";
        } else if (finalString.length() < 3) {
            return "Short_" + finalString;
        } else if (finalString.length() >= 3 && finalString.length() <= 5) {
            return finalString + "_Medium";
        } else {
            return "Long_" + finalString + "_Processed";
        }
    }
}

