import java.util.HashSet;
import java.util.Set;

public class NumberComparator {
    public static String analyzeNumbers(List<Integer> numbers) {
        if (numbers.isEmpty()) {
            return "Error: No numbers provided.";
        }

        for (Integer number : numbers) {
            if (number == null) {
                throw new NullPointerException("List must not contain null elements");
            }
        }

        Set<Integer> uniqueNumbers = new HashSet<>();
        for (Integer number : numbers) {
            if (!uniqueNumbers.add(number)) {
                return "Error: All input numbers must be unique. Found duplicates.";
            }
        }

        int largest = numbers.get(0);
        int smallest = numbers.get(0);

        for (int number : numbers) {
            if (number > largest) {
                largest = number;
            }
            if (number < smallest) {
                smallest = number;
            }
        }

        int range = largest - smallest;
        int uniqueCount = uniqueNumbers.size();

        return "Analysis results:\n" +
               "Largest number: " + largest + "\n" +
               "Smallest number: " + smallest + "\n" +
               "Range: " + range + "\n" +
               "Unique values count: " + uniqueCount;
    }
}

