import java.util.*;

class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;

    TreeNode() {}

    TreeNode(int val) {
        this.val = val;
    }

    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

class TreeAnalyzer {
    public Map<String, Integer> analyzeTree(TreeNode root) {
        Map<String, Integer> result = new HashMap<>();

        // Count nodes
        int count = countNodes(root);
        result.put("nodeCount", count);

        // Calculate max ancestor difference
        int maxDiff = calculateMaxAncestorDiff(root, root == null ? 0 : root.val, root == null ? 0 : root.val);
        result.put("maxDiff", maxDiff);

        return result;
    }

    private int countNodes(TreeNode node) {
        if (node == null) {
            return 0;
        }
        return 1 + countNodes(node.left) + countNodes(node.right);
    }

    private int calculateMaxAncestorDiff(TreeNode node, int minAncestor, int maxAncestor) {
        if (node == null) {
            return 0;
        }

        // Calculate the difference with current node and ancestors
        int currentDiff = Math.max(Math.abs(node.val - minAncestor), Math.abs(node.val - maxAncestor));

        // Update min and max ancestors for children
        int newMin = Math.min(minAncestor, node.val);
        int newMax = Math.max(maxAncestor, node.val);

        // Recursively calculate for children
        int leftDiff = calculateMaxAncestorDiff(node.left, newMin, newMax);
        int rightDiff = calculateMaxAncestorDiff(node.right, newMin, newMax);

        // Return the maximum difference found
        return Math.max(currentDiff, Math.max(leftDiff, rightDiff));
    }
}

