import java.util.*;

public class ChatMessageProcessor {
    private Map<String, List<String>> userMessages;
    private List<String> activeUsers;

    public ChatMessageProcessor() {
        this.userMessages = new HashMap<>();
        this.activeUsers = new ArrayList<>();
    }

    public List<String> userJoins(String username) {
        // Check if username is already taken
        if (activeUsers.contains(username)) {
            List<String> error = new ArrayList<>();
            error.add("Error: Username " + username + " is already taken");
            return error;
        }

        // Add user to active users list
        activeUsers.add(username);

        // Initialize empty message list for this user
        userMessages.put(username, new ArrayList<>());

        // Return empty list of notifications since no other users exist yet
        return new ArrayList<>();
    }

    public List<String> userLeaves(String username) {
        // Check if user exists
        if (!activeUsers.contains(username)) {
            List<String> error = new ArrayList<>();
            error.add("Error: User " + username + " not found");
            return error;
        }

        // Remove user from active users
        activeUsers.remove(username);

        // Remove user's messages
        userMessages.remove(username);

        // Notify all remaining users
        List<String> notifications = new ArrayList<>();
        String notificationMessage = "[Server] - " + username + " has left";

        for (String user : activeUsers) {
            notifications.add(notificationMessage);
        }

        return notifications;
    }

    // Additional helper methods that might be useful
    public void addMessage(String username, String message) {
        if (userMessages.containsKey(username)) {
            userMessages.get(username).add(message);
        }
    }

    public List<String> getMessages(String username) {
        return userMessages.getOrDefault(username, new ArrayList<>());
    }

    public List<String> getActiveUsers() {
        return new ArrayList<>(activeUsers);
    }
}

