    private List<String> activeUsers;

    public ChatMessageProcessor() {
        this.userMessages = new HashMap<>();
        this.activeUsers = new ArrayList<>();
    }

    public List<String> userJoins(String username) {
        // Check if username is already taken
        if (activeUsers.contains(username)) {
            List<String> error = new ArrayList<>();
            error.add("Error: Username " + username + " is already taken");
            return error;
        }

        // Add user to active users list
        activeUsers.add(username);

        // Initialize empty message list for this user
        userMessages.put(username, new ArrayList<>());

        // Return empty list of notifications since no other users exist yet
        return new ArrayList<>();
    }

    public List<String> userLeaves(String username) {
        // Check if user exists
        if (!activeUsers.contains(username)) {
            List<String> error = new ArrayList<>();
            error.add("Error: User " + username + " not found");
            return error;
