class FileUploadUtil {

    public static String getFilename(String contentDisposition) {
        if (contentDisposition == null || contentDisposition.isEmpty()) {
            return null;
        }

        // Look for filename parameter
        String filenamePrefix = "filename=";
        int filenameIndex = contentDisposition.indexOf(filenamePrefix);

        if (filenameIndex == -1) {
            return null;
        }

        // Extract the filename value
        int startIndex = filenameIndex + filenamePrefix.length();
        String filenamePart = contentDisposition.substring(startIndex);

        // Handle quoted filenames
        if (filenamePart.startsWith("\"")) {
            int endIndex = filenamePart.indexOf("\"", 1);
            if (endIndex != -1) {
                return filenamePart.substring(1, endIndex);
            }
        } else {
            // Handle unquoted filenames - find the end (space, semicolon, or end of string)
            int endIndex = filenamePart.indexOf(";");
            if (endIndex == -1) {
                endIndex = filenamePart.indexOf(" ");
            }
            if (endIndex != -1) {
                return filenamePart.substring(0, endIndex);
            } else {
                return filenamePart;
            }
        }

        return null;
