    private static String extractFilename(String contentDisposition, String parameter) {
        int index = contentDisposition.indexOf(parameter);
        if (index == -1) {
            return null;
        }

        int startIndex = index + parameter.length();
        String filenamePart = contentDisposition.substring(startIndex);

        // Handle quoted filenames (both single and double quotes)
        if (filenamePart.startsWith("\"")) {
            int endIndex = filenamePart.indexOf("\"", 1);
            if (endIndex != -1) {
                return filenamePart.substring(1, endIndex);
            }
        } else if (filenamePart.startsWith("'")) {
            int endIndex = filenamePart.indexOf("'", 1);
            if (endIndex != -1) {
                return filenamePart.substring(1, endIndex);
            }
        } else {
            // Handle unquoted filenames - find the end (semicolon, comma, space, or end of string)
            int endIndex = filenamePart.length();
            int semicolonIndex = filenamePart.indexOf(";");
            int commaIndex = filenamePart.indexOf(",");
            int spaceIndex = filenamePart.indexOf(" ");

            if (semicolonIndex != -1 && semicolonIndex < endIndex) {
                endIndex = semicolonIndex;
            }
            if (commaIndex != -1 && commaIndex < endIndex) {
                endIndex = commaIndex;
            }
            if (spaceIndex != -1 && spaceIndex < endIndex) {
                endIndex = spaceIndex;
            }

            if (endIndex > 0) {
                return filenamePart.substring(0, endIndex);
            } else {
                return filenamePart;
            }
        }

        return null;
    }

    private static String decodeExtendedFilename(String filename) {
        // Handle RFC 5987 encoded filenames (filename*=UTF-8''filename.txt)
        int firstSingleQuote = filename.indexOf("'");
        if (firstSingleQuote != -1) {
            int secondSingleQuote = filename.indexOf("'", firstSingleQuote + 1);
            if (secondSingleQuote != -1) {
                // Extract the actual filename part after the second single quote
                return filename.substring(secondSingleQuote + 1);
            }
        }
        return filename;
    }

