import java.util.*;

class GraphAnalyzer {
    public static Map<String, Object> analyzeGraph(int[][] graph, int source) {
        int n = graph.length;
        int[] distances = new int[n];
        int[] prev = new int[n];
        boolean[] visited = new boolean[n];

        // Initialize distances and previous array
        Arrays.fill(distances, Integer.MAX_VALUE);
        Arrays.fill(prev, -1);
        distances[source] = 0;

        // Priority queue to store vertices with their distances
        PriorityQueue<Vertex> pq = new PriorityQueue<>(Comparator.comparingInt(v -> v.distance));
        pq.offer(new Vertex(source, 0));

        while (!pq.isEmpty()) {
            Vertex current = pq.poll();
            int u = current.index;

            if (visited[u]) continue;
            visited[u] = true;

            // Check all neighbors of current vertex
            for (int v = 0; v < n; v++) {
                // If there is an edge and the vertex is not visited
                if (graph[u][v] != 0 && !visited[v]) {
                    int newDist = distances[u] + graph[u][v];

                    // If we found a shorter path to v
                    if (newDist < distances[v]) {
                        distances[v] = newDist;
                        prev[v] = u;
                        pq.offer(new Vertex(v, newDist));
                    }
                }
            }
        }

        // Build result map
        Map<String, Object> result = new HashMap<>();
        result.put("distances", distances);

        // Build paths for all vertices
        Map<Integer, List<Integer>> paths = new HashMap<>();
        for (int i = 0; i < n; i++) {
            if (i != source) {
                paths.put(i, buildPath(prev, source, i));
            }
        }
        result.put("paths", paths);

        return result;
    }

    private static List<Integer> buildPath(int[] prev, int source, int target) {
        List<Integer> path = new ArrayList<>();
        int current = target;

        // Backtrack from target to source using prev array
        while (current != -1) {
            path.add(current);
            current = prev[current];
        }

        // Reverse the path to get it from source to target
        Collections.reverse(path);

        // If the path doesn't start with source, it means there's no path
        if (!path.isEmpty() && path.get(0) != source) {
            return new ArrayList<>(); // Return empty list if no path exists
        }

        return path;
    }

    private static class Vertex {
        int index;
        int distance;

        Vertex(int index, int distance) {
            this.index = index;
            this.distance = distance;
        }
    }
}

