        Arrays.fill(prev, -1);
        distances[source] = 0;

        // Priority queue to store vertices with their distances
        PriorityQueue<Vertex> pq = new PriorityQueue<>((v1, v2) -> Integer.compare(v1.distance, v2.distance));
        pq.offer(new Vertex(source, 0));

        while (!pq.isEmpty()) {
            Vertex current = pq.poll();
            int u = current.index;

            if (visited[u]) continue;
            visited[u] = true;
            visitedCount++; // Increment counter when vertex is processed

            // Check all neighbors
            for (int v = 0; v < n; v++) {
                if (graph[u][v] != 0 && !visited[v]) {
                    int newDist = distances[u] + graph[u][v];

                    if (newDist < distances[v]) {
                        distances[v] = newDist;
                        prev[v] = u;
                        pq.offer(new Vertex(v, newDist));
                    }
                }
            }
        }

        // Build result map
        Map<String, Object> result = new HashMap<>();
        result.put("distances", distances);

        // Build paths for all vertices
        List<List<Integer>> paths = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            paths.add(buildPath(prev, source, i));
        }
        result.put("paths", paths);

        // Add visited count to result
        result.put("visitedCount", visitedCount);

        // Compute maximum shortest distance among reachable vertices
        int maxDistance = 0;
        for (int i = 0; i < n; i++) {
            if (distances[i] != Integer.MAX_VALUE && distances[i] > maxDistance) {
                maxDistance = distances[i];
            }
        }
        result.put("maxDistance", maxDistance);

        return result;
    }

    private static List<Integer> buildPath(int[] prev, int source, int target) {
        List<Integer> path = new ArrayList<>();
        int current = target;

        // Backtrack from target to source
        while (current != -1) {
            path.add(current);
            current = prev[current];
        }

        // Reverse to get path from source to target
        Collections.reverse(path);

        // Return empty list if no path exists (when source is not the first element)
        if (!path.isEmpty() && path.get(0) != source) {
            return new ArrayList<>();
        }

        return path;
    }

    private static class Vertex {
        int index;
        int distance;

        Vertex(int index, int distance) {
            this.index = index;
            this.distance = distance;
        }
    }
}
