import java.util.Map;
import java.util.HashMap;

class DateUtils {
    private static final String[] DAYS_OF_WEEK = {
        "SUNDAY", "MONDAY", "TUESDAY", "WEDNESDAY", "THURSDAY", "FRIDAY", "SATURDAY"
    };

    public static Map<String, String> analyzeDate(int day, int month, int year) {
        if (!isValidDate(day, month, year)) {
            throw new IllegalArgumentException("Invalid date");
        }
        return new HashMap<>();
    }

    private static boolean isLeapYear(int year) {
        return (year % 4 == 0) && (year % 100 != 0 || year % 400 == 0);
    }

    private static int getDaysInMonth(int month, int year) {
        if (month < 1 || month > 12 || year < 1) {
            return -1; // Invalid input
        }

        switch (month) {
            case 1: case 3: case 5: case 7: case 8: case 10: case 12:
                return 31;
            case 4: case 6: case 9: case 11:
                return 30;
            case 2:
                return isLeapYear(year) ? 29 : 28;
            default:
                return -1; // Should not reach here due to earlier check
        }
    }

    private static boolean isValidDate(int day, int month, int year) {
        // Check if year is valid (positive)
        if (year < 1) {
            return false;
        }

        // Check if month is between 1 and 12 inclusive
        if (month < 1 || month > 12) {
            return false;
        }

        // Get the maximum days for the given month and year
        int maxDays = getDaysInMonth(month, year);

        // Check if day is within valid range
        if (day < 1 || day > maxDays) {
            return false;
        }

