import java.util.List;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.text.DecimalFormat;

public class RedditFeedAnalyzer {
    public String analyzeAndFormatFeed(List<RedditFeedItem> feedItems, int minScore) {
        if (feedItems == null || feedItems.isEmpty()) {
            return "No feed items to analyze";
        }

        List<RedditFeedItem> filteredItems = new ArrayList<>();
        int totalScore = 0;
        int totalComments = 0;

        for (RedditFeedItem item : feedItems) {
            if (item.getScore() >= minScore) {
                filteredItems.add(item);
                totalScore += item.getScore();
                totalComments += item.getNumComments();
            }
        }

        int count = filteredItems.size();
        DecimalFormat df = new DecimalFormat("0.00");
        String averageScore = df.format(count > 0 ? (double) totalScore / count : 0.00);
        String averageComments = df.format(count > 0 ? (double) totalComments / count : 0.00);

        StringBuilder result = new StringBuilder();
        result.append("Feed Analysis Summary: Total items: ").append(count)
              .append("\nAverage score: ").append(averageScore)
              .append("\nAverage comments: ").append(averageComments);

        if (count > 0) {
            // Sort by score in descending order
            Collections.sort(filteredItems, new Comparator<RedditFeedItem>() {
                @Override
                public int compare(RedditFeedItem a, RedditFeedItem b) {
                    return Integer.compare(b.getScore(), a.getScore());
                }
            });

            result.append("\nTop 3 items by score:");
            int limit = Math.min(3, count);
            for (int i = 0; i < limit; i++) {
                RedditFeedItem item = filteredItems.get(i);
                result.append("\n").append(i + 1).append(". ")
                      .append(item.getTitle())
                      .append(" (Score: ").append(item.getScore())
                      .append(", Comments: ").append(item.getNumComments()).append(")");
            }
        }

        return result.toString();
    }
}

