import java.util.*;

class AuthService {
    public Map<String, Object> processOAuth2User(String provider, 
                                               Map<String, Object> userAttributes,
                                               Map<String, User> existingUsers,
                                               Set<Role> availableRoles) {
        // Input validation
        if (provider == null || provider.isEmpty()) {
            throw new IllegalArgumentException("Provider cannot be null or empty");
        }

        if (userAttributes == null || userAttributes.isEmpty()) {
            throw new IllegalArgumentException("User attributes cannot be null or empty");
        }

        if (!userAttributes.containsKey("email")) {
            throw new IllegalArgumentException("Email is missing from user attributes");
        }

        String email = (String) userAttributes.get("email");
        Map<String, Object> result = new HashMap<>();
        result.put("provider", provider);

        if (existingUsers.containsKey(email)) {
            User existingUser = existingUsers.get(email);
            // Update name and lastname if provided, otherwise keep existing values
            String newName = (String) userAttributes.getOrDefault("given_name", existingUser.getName());
            String newLastname = (String) userAttributes.getOrDefault("family_name", existingUser.getLastname());
            existingUser.setName(newName);
            existingUser.setLastname(newLastname);

            result.put("status", "authenticated");
            result.put("user", existingUser);
        } else {
            User newUser = registerNewUser(email, provider, userAttributes, availableRoles);
            existingUsers.put(email, newUser);
            result.put("status", "registered");
            result.put("user", newUser);
        }

        // Add roles to the result
        User user = (User) result.get("user");
        Set<String> roleNames = new HashSet<>();
        if (user.getRoles() != null) {
            for (Role role : user.getRoles()) {
                roleNames.add(role.getName());
            }
        }
        result.put("roles", roleNames);

        return result;
    }

    private User registerNewUser(String email, String provider, Map<String, Object> userAttributes, Set<Role> availableRoles) {
