            this.data = data;
            this.next = null;
        }
    }

    private Node front;
    private Node rear;
    private int size;
    private int capacity;

    // Default constructor with default capacity
    public EnhancedQueue() {
        this.front = null;
        this.rear = null;
        this.size = 0;
        this.capacity = DEFAULT_CAPACITY;
    }

