        this.states = new HashSet<>();
        this.finalStates = new HashSet<>();
        this.initialState = null;
    }

    public void addState(State state) {
        states.add(state);
        if (initialState == null) {
            initialState = state;
        }
        if (state.isFinal()) {
            finalStates.add(state);
        }
    }

