            if (currentState == null) {
                return false;
            }
        }

        return currentState.isFinal();
    }

    public Set<State> getStates() {
        return new HashSet<>(states);
    }

    public Set<State> getFinalStates() {
        return new HashSet<>(finalStates);
    }
}

