import java.util.*;

public class DataMatcher {

    public Map<String, List<String[]>> enhancedMatch(List<String[]> dataset1, List<String[]> dataset2, 
                                                     int matchStrategy, int[] keyIndices) {
        Map<String, List<String[]>> result = new HashMap<>();
        List<String[]> matched = new ArrayList<>();
        List<String[]> unmatched1 = new ArrayList<>();
        List<String[]> unmatched2 = new ArrayList<>();

        result.put("matched", matched);
        result.put("unmatched1", unmatched1);
        result.put("unmatched2", unmatched2);

        if (matchStrategy != 1) {
            // For now, only handle exact matching
            return result;
        }

        // Create a map for dataset2 for efficient lookup
        Map<String, List<String[]>> dataset2Map = new HashMap<>();
        for (String[] record : dataset2) {
            String key = createKey(record, keyIndices);
            dataset2Map.computeIfAbsent(key, k -> new ArrayList<>()).add(record);
        }

        // Track which records from dataset2 have been matched
        Set<String> matchedKeys = new HashSet<>();

        // Process dataset1
        for (String[] record1 : dataset1) {
            String key = createKey(record1, keyIndices);
            if (dataset2Map.containsKey(key)) {
                // Match found
                matchedKeys.add(key);
                // For now, just take the first matching record from dataset2
                String[] record2 = dataset2Map.get(key).get(0);
                // Combine the records
                String[] combined = new String[record1.length + record2.length];
                System.arraycopy(record1, 0, combined, 0, record1.length);
                System.arraycopy(record2, 0, combined, record1.length, record2.length);
                matched.add(combined);
            } else {
                // No match found
                unmatched1.add(record1);
            }
        }

        // Find unmatched records in dataset2
        for (String[] record2 : dataset2) {
            String key = createKey(record2, keyIndices);
            if (!matchedKeys.contains(key)) {
                unmatched2.add(record2);
            }
        }

        return result;
    }

    private String createKey(String[] record, int[] keyIndices) {
        StringBuilder key = new StringBuilder();
        for (int i = 0; i < keyIndices.length; i++) {
            if (keyIndices[i] < record.length) {
                if (i > 0) {
                    key.append("|"); // Use a separator to distinguish between fields
                }
                key.append(record[keyIndices[i]].trim());
            }
        }
        return key.toString();
    }
}

