    public int getTotalPages() { return totalPages; }
    public int getStartItem() { return startItem; }
    public int getEndItem() { return endItem; }
    public List<Integer> getVisiblePages() { return visiblePages; }
}

public class PaginationManager {

    public PaginationResult calculatePagination(int totalItems, int pageSize, int currentPage) {
        // Validate inputs
        if (totalItems < 0) {
            throw new IllegalArgumentException("totalItems cannot be negative");
        }
        if (pageSize <= 0) {
            throw new IllegalArgumentException("pageSize must be positive");
        }
        if (currentPage <= 0) {
            throw new IllegalArgumentException("currentPage must be positive");
        }

        // Calculate total pages
        int totalPages = 0;
        if (totalItems > 0) {
            totalPages = (int) Math.ceil((double) totalItems / pageSize);
        }

        // Adjust current page if it exceeds total pages
        if (currentPage > totalPages && totalPages > 0) {
            currentPage = totalPages;
        }

        // For zero totalItems, ensure currentPage is 0 and no items are displayed
        if (totalItems == 0) {
            currentPage = 0;
            return new PaginationResult(totalItems, pageSize, currentPage, totalPages, 
                                      0, 0, new ArrayList<>());
        }

        // Calculate start and end items (1-based indexing)
        int startItem = (currentPage - 1) * pageSize + 1;
        int endItem = Math.min(currentPage * pageSize, totalItems);

        // Calculate visible pages
        List<Integer> visiblePages = calculateVisiblePages(currentPage, totalPages);

        return new PaginationResult(totalItems, pageSize, currentPage, totalPages, 
                                  startItem, endItem, visiblePages);
    }

    private List<Integer> calculateVisiblePages(int currentPage, int totalPages) {
        List<Integer> visiblePages = new ArrayList<>();

        if (totalPages <= 0) {
            return visiblePages;
        }

        // Always add the first page if there are pages
        visiblePages.add(1);

        // If there's only one page, we're done
        if (totalPages == 1) {
            return visiblePages;
        }

        // Calculate the range of pages to show around current page
        int startRange = Math.max(2, currentPage - 2);
        int endRange = Math.min(totalPages - 1, currentPage + 2);

        // Add ellipsis if there's a gap between first page and start range
        if (startRange > 2) {
            visiblePages.add(-1); // Ellipsis
        }

        // Add the page range around current page
        for (int i = startRange; i <= endRange; i++) {
            visiblePages.add(i);
        }

        // Add ellipsis if there's a gap between end range and last page
        if (endRange < totalPages - 1) {
            visiblePages.add(-1); // Ellipsis
        }

        // Always add the last page if there's more than one page
        if (totalPages > 1) {
            visiblePages.add(totalPages);
        }

        return visiblePages;
    }
}
