public class EnhancedBinaryHeap {
    private int[] heap;
    private int size;
    private static final int DEFAULT_CAPACITY = 10;

    public EnhancedBinaryHeap() {
        heap = new int[DEFAULT_CAPACITY];
        size = 0;
    }

    public void insert(int element) {
        if (size == heap.length - 1) {
            resize();
        }

        size++;
        heap[size] = element;
        heapifyUp(size);
    }

    public int deleteRoot() {
        if (isEmpty()) {
            throw new IllegalStateException("Heap is empty");
        }

        int root = heap[1];
        heap[1] = heap[size];
        size--;
        heapifyDown(1);

        return root;
    }

    public int peekRoot() {
        if (isEmpty()) {
            throw new IllegalStateException("Heap is empty");
        }
        return heap[1];
    }

    public boolean isEmpty() {
        return size == 0;
    }

    public int size() {
        return size;
    }

    public void makeEmpty() {
        size = 0;
    }

    private void heapifyUp(int index) {
        while (index > 1 && heap[index] < heap[parent(index)]) {
            swap(index, parent(index));
            index = parent(index);
        }
    }

    private void heapifyDown(int index) {
        while (leftChild(index) <= size) {
            int smallerChild = leftChild(index);

            if (rightChild(index) <= size && heap[rightChild(index)] < heap[smallerChild]) {
                smallerChild = rightChild(index);
            }

            if (heap[index] <= heap[smallerChild]) {
                break;
            }

            swap(index, smallerChild);
            index = smallerChild;
        }
    }

    private int parent(int index) {
        return index / 2;
    }

    private int leftChild(int index) {
        return index * 2;
    }

    private int rightChild(int index) {
        return index * 2 + 1;
    }

    private void swap(int i, int j) {
        int temp = heap[i];
        heap[i] = heap[j];
        heap[j] = temp;
    }

    private void resize() {
        int[] newHeap = new int[heap.length * 2];
        System.arraycopy(heap, 0, newHeap, 0, heap.length);
        heap = newHeap;
    }
}

