public class EnhancedBinaryHeap {
    private int[] heap;
    private int[] vertex1;
    private int[] vertex2;
    private int size;
    private boolean isMinHeap;
    private static final int DEFAULT_CAPACITY = 10;

    public EnhancedBinaryHeap() {
        this(true);
    }

    public EnhancedBinaryHeap(boolean isMinHeap) {
        this.heap = new int[DEFAULT_CAPACITY];
        this.vertex1 = new int[DEFAULT_CAPACITY];
        this.vertex2 = new int[DEFAULT_CAPACITY];
        this.size = 0;
        this.isMinHeap = isMinHeap;
    }

    public EnhancedBinaryHeap(int[] items, boolean isMinHeap) {
        this.isMinHeap = isMinHeap;
        this.size = items.length;
        this.heap = new int[size + 1];
        this.vertex1 = new int[size + 1];
        this.vertex2 = new int[size + 1];

        // Copy items into heap array (1-indexed)
        for (int i = 0; i < items.length; i++) {
            heap[i + 1] = items[i];
        }

        buildHeap();
    }

    public void insert(int element, int v1, int v2) {
        if (size == heap.length - 1) {
            resize();
        }

        size++;
        heap[size] = element;
        vertex1[size] = v1;
        vertex2[size] = v2;
        heapifyUp(size);
    }

    public int deleteRoot() {
        if (isEmpty()) {
            throw new IllegalStateException("Heap is empty");
        }

        int root = heap[1];
        heap[1] = heap[size];
        vertex1[1] = vertex1[size];
        vertex2[1] = vertex2[size];
        size--;
        heapifyDown(1);

        return root;
    }

    public int peekRoot() {
        if (isEmpty()) {
            throw new IllegalStateException("Heap is empty");
        }
        return heap[1];
    }

    public int[] peekRootVertices() {
        if (isEmpty()) {
            throw new IllegalStateException("Heap is empty");
        }
        return new int[]{vertex1[1], vertex2[1]};
    }

    public boolean isEmpty() {
        return size == 0;
    }

    public int size() {
        return size;
    }

    public void makeEmpty() {
        size = 0;
    }

    public int[] heapSort() {
        int[] sorted = new int[size];
        int originalSize = size;

        for (int i = 0; i < sorted.length; i++) {
            sorted[i] = deleteRoot();
        }

        return sorted;
    }

    private void buildHeap() {
        for (int i = size / 2; i >= 1; i--) {
            heapifyDown(i);
        }
    }

    private void heapifyUp(int index) {
