import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.HashMap;
import java.util.Map;

class TimeDifferenceCalculator {
    private static final String DEFAULT_DATETIME_PATTERN = "yyyy-MM-dd HH:mm:ss";

    public static Map<String, Object> calculateDetailedTimeDifference(String earlierTime, String laterTime) 
            throws ParseException {
        SimpleDateFormat formatter = new SimpleDateFormat(DEFAULT_DATETIME_PATTERN);

        Date earlierDate = formatter.parse(earlierTime);
        Date laterDate = formatter.parse(laterTime);

        long diffInMillis = laterDate.getTime() - earlierDate.getTime();

        long seconds = diffInMillis / 1000;
        long minutes = seconds / 60;
        long hours = minutes / 60;
        long days = hours / 24;
        long weeks = days / 7;

        Map<String, Object> result = new HashMap<>();
        result.put("seconds", seconds);
        result.put("minutes", minutes);
        result.put("hours", hours);
        result.put("days", days);
        result.put("weeks", weeks);

        // Create human-readable string
        StringBuilder humanReadable = new StringBuilder();
        boolean hasValue = false;

        if (weeks > 0) {
            humanReadable.append(weeks).append(" week").append(weeks > 1 ? "s" : "");
            hasValue = true;
        }

        if (days % 7 > 0) {
            if (hasValue) humanReadable.append(", ");
            humanReadable.append(days % 7).append(" day").append((days % 7) > 1 ? "s" : "");
            hasValue = true;
        }

        if (hours % 24 > 0) {
            if (hasValue) humanReadable.append(", ");
            humanReadable.append(hours % 24).append(" hour").append((hours % 24) > 1 ? "s" : "");
            hasValue = true;
        }

        if (minutes % 60 > 0) {
            if (hasValue) humanReadable.append(", ");
            humanReadable.append(minutes % 60).append(" minute").append((minutes % 60) > 1 ? "s" : "");
            hasValue = true;
        }

        if (seconds % 60 > 0) {
            if (hasValue) humanReadable.append(", ");
            humanReadable.append(seconds % 60).append(" second").append((seconds % 60) > 1 ? "s" : "");
        }

        if (humanReadable.length() == 0) {
            humanReadable.append("0 seconds");
        }

        result.put("humanReadable", humanReadable.toString());

        return result;
    }
}

