import java.util.*;

class PathFinder {

    public static class PathAnalysis {
        private final int totalPaths;
        private final List<List<int[]>> allPaths;

        public PathAnalysis(int totalPaths, List<List<int[]>> allPaths) {
            this.totalPaths = totalPaths;
            this.allPaths = allPaths;
        }

        public int getTotalPaths() {
            return totalPaths;
        }

        public List<List<int[]>> getAllPaths() {
            return allPaths;
        }

        @Override
        public String toString() {
            return "PathAnalysis{totalPaths=" + totalPaths + ", allPaths=" + allPaths.size() + "}";
        }
    }

    public PathAnalysis findUniquePathsWithAnalysis(int[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return new PathAnalysis(0, new ArrayList<>());
        }

        int rows = grid.length;
        int cols = grid[0].length;

        // DP table to store number of paths to each cell
        int[][] dp = new int[rows][cols];

        // Initialize first cell
        dp[0][0] = 1;

        // Fill first row
        for (int j = 1; j < cols; j++) {
            dp[0][j] = dp[0][j-1];
        }

        // Fill first column
        for (int i = 1; i < rows; i++) {
            dp[i][0] = dp[i-1][0];
        }

        // Fill the rest of the dp table
        for (int i = 1; i < rows; i++) {
            for (int j = 1; j < cols; j++) {
                dp[i][j] = dp[i-1][j] + dp[i][j-1];
            }
        }

        // Generate all paths if grid is not too large
        List<List<int[]>> allPaths = new ArrayList<>();
        if (rows <= 10 && cols <= 10) { // Limit path generation for performance
            List<int[]> currentPath = new ArrayList<>();
            currentPath.add(new int[]{0, 0});
            generatePaths(grid, 0, 0, currentPath, allPaths);
        }

        return new PathAnalysis(dp[rows-1][cols-1], allPaths);
    }

    private void generatePaths(int[][] grid, int row, int col, List<int[]> currentPath, List<List<int[]>> allPaths) {
        int rows = grid.length;
        int cols = grid[0].length;

        // If we reached the destination
        if (row == rows - 1 && col == cols - 1) {
            allPaths.add(new ArrayList<>(currentPath));
            return;
        }

        // Move right
        if (col + 1 < cols) {
            currentPath.add(new int[]{row, col + 1});
            generatePaths(grid, row, col + 1, currentPath, allPaths);
            currentPath.remove(currentPath.size() - 1);
        }

        // Move down
        if (row + 1 < rows) {
            currentPath.add(new int[]{row + 1, col});
            generatePaths(grid, row + 1, col, currentPath, allPaths);
            currentPath.remove(currentPath.size() - 1);
        }
    }
}

