        int[][] dp = new int[rows][cols];

        // Initialize first cell
        dp[0][0] = 1;

        // Fill first row
        for (int j = 1; j < cols; j++) {
            dp[0][j] = dp[0][j-1];
        }

        // Fill first column
        for (int i = 1; i < rows; i++) {
            dp[i][0] = dp[i-1][0];
        }

        // Fill the rest of the dp table
        for (int i = 1; i < rows; i++) {
            for (int j = 1; j < cols; j++) {
                dp[i][j] = dp[i-1][j] + dp[i][j-1];
            }
        }

        // For a grid of size rows x cols, all paths have the same length: rows + cols - 2
        int pathLength = rows + cols - 2;

        // Generate a sample path
        List<String> samplePath = new ArrayList<>();
        int currentRow = 0, currentCol = 0;
        samplePath.add("(" + currentRow + "," + currentCol + ")");

        while (currentRow < rows - 1 || currentCol < cols - 1) {
            if (currentRow == rows - 1) {
                // Can only move right
                currentCol++;
                samplePath.add("(" + currentRow + "," + currentCol + ")");
            } else if (currentCol == cols - 1) {
