        if (node == null) {
            return;
        }

        // If this node marks the end of a word, add it to the list
        if (node.isEndOfWord) {
            words.add(current.toString());
        }

        // Recursively traverse all children
        for (int i = 0; i < node.children.length; i++) {
            if (node.children[i] != null) {
                // Append the character of the child node
                current.append(node.children[i].character);
                // Recursively collect words from this child
                collectWords(node.children[i], current, words);
                // Backtrack: remove the character we just added
                current.deleteCharAt(current.length() - 1);
            }
        }
    }

    private void insert(TrieNode[] array, TrieNode element) {
        char ch = element.character;
        int insertIndex = 0;

        // Find the correct position to insert
        while (insertIndex < array.length && array[insertIndex] != null && array[insertIndex].character < ch) {
            insertIndex++;
        }

        // Shift elements to the right to make space
        for (int i = array.length - 1; i > insertIndex; i--) {
            array[i] = array[i - 1];
        }

        // Insert the element
        array[insertIndex] = element;
    }

    private class TrieNode {
        char character;
        boolean isEndOfWord;
        int frequency;
        TrieNode[] children;

        public TrieNode() {
            this.children = new TrieNode[26]; // for lowercase letters a-z
            this.isEndOfWord = false;
            this.frequency = 0;
        }

        public TrieNode(char character) {
            this();
            this.character = character;
        }

        public TrieNode addChild(char ch) {
            int index = ch - 'a';
            if (children[index] == null) {
                TrieNode newNode = new TrieNode(ch);
                insert(children, newNode);
                return newNode;
            }
            return children[index];
        }

        public TrieNode getChild(char ch) {
            int index = ch - 'a';
            return children[index];
        }

        public void incrementFrequency() {
            this.frequency++;
        }

        public int getFrequency() {
            return this.frequency;
        }
    }
}
