class SubsetGenerator {
    public List<List<Integer>> generateSubsets(int[] nums) {
        List<List<Integer>> result = new ArrayList<>();
        backtrack(nums, 0, new ArrayList<>(), result);
        return result;
    }

    private void backtrack(int[] nums, int start, List<Integer> currentSubset, List<List<Integer>> result) {
        // Add current subset to result
        result.add(new ArrayList<>(currentSubset));

        // Generate subsets by including each remaining element
        for (int i = start; i < nums.length; i++) {
            // Include current element
            currentSubset.add(nums[i]);

            // Recursively generate subsets with this element included
            backtrack(nums, i + 1, currentSubset, result);

            // Backtrack: remove current element to try next possibility
            currentSubset.remove(currentSubset.size() - 1);
        }
    }
}

