        if (k <= 0 || n <= 0) {
            throw new IllegalArgumentException("Number of eggs and floors must be positive");
        }

        // Create a 2D DP table where dp[i][j] represents minimum attempts
        // needed with i eggs and j floors
        int[][] dp = new int[k + 1][n + 1];

        // Base cases:
        // With 0 floors, 0 attempts needed
        // With 1 floor, 1 attempt needed
        for (int i = 1; i <= k; i++) {
            dp[i][0] = 0;
            dp[i][1] = 1;
        }

        // With 1 egg, we need j attempts for j floors (linear search)
        for (int j = 1; j <= n; j++) {
            dp[1][j] = j;
        }

        // Fill the DP table for remaining cases
        for (int i = 2; i <= k; i++) {
            for (int j = 2; j <= n; j++) {
                dp[i][j] = Integer.MAX_VALUE;

                // Try dropping from each floor x (1 to j)
                for (int x = 1; x <= j; x++) {
                    // If egg breaks: we have i-1 eggs and x-1 floors below
                    // If egg doesn't break: we have i eggs and j-x floors above
                    int attempts = 1 + Math.max(dp[i-1][x-1], dp[i][j-x]);
                    dp[i][j] = Math.min(dp[i][j], attempts);
                }
            }
        }

        return dp[k][n];
    }

    public static int solveEggDropMathematical(int k, int n) {
        // Validate input parameters
        if (k <= 0 || n <= 0) {
            throw new IllegalArgumentException("Number of eggs and floors must be positive");
        }

        // Mathematical approach using binomial coefficients
        // We need to find minimum attempts x such that C(x,1) + C(x,2) + ... + C(x,k) >= n
        int attempts = 0;
        while (true) {
            attempts++;
            long sum = 0;
            long binomial = 1;

            // Calculate sum of C(attempts, 1) + C(attempts, 2) + ... + C(attempts, k)
            for (int i = 1; i <= k && sum < n; i++) {
                binomial = binomial * (attempts - i + 1) / i;
                sum += binomial;
            }

            if (sum >= n) {
                return attempts;
            }
        }
    }

    public static int solveEggDropBinarySearch(int k, int n) {
        // Validate input parameters
        if (k <= 0 || n <= 0) {
            throw new IllegalArgumentException("Number of eggs and floors must be positive");
        }

        // Binary search approach with memoization
        int[][] memo = new int[k + 1][n + 1];
        return binarySearchHelper(k, n, memo);
    }

    private static int binarySearchHelper(int eggs, int floors, int[][] memo) {
        // Base cases
        if (floors == 0 || floors == 1) {
            return floors;
        }
        if (eggs == 1) {
            return floors;
        }

        // Check memoization table
        if (memo[eggs][floors] != 0) {
            return memo[eggs][floors];
        }

        // Binary search to find optimal floor
        int low = 1;
        int high = floors;
        int result = Integer.MAX_VALUE;

        while (low <= high) {
            int mid = (low + high) / 2;

            // Calculate attempts if egg breaks and doesn't break
            int breaks = binarySearchHelper(eggs - 1, mid - 1, memo);
            int notBreaks = binarySearchHelper(eggs, floors - mid, memo);

            // Take the worst case and add current attempt
            int attempts = 1 + Math.max(breaks, notBreaks);
            result = Math.min(result, attempts);

            // Adjust search range based on which side is worse
            if (breaks < notBreaks) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        // Store in memoization table
        memo[eggs][floors] = result;
        return result;
    }

