            this.binarySearchResult = binarySearchResult;
            this.dpTime = dpTime;
            this.mathematicalTime = mathematicalTime;
            this.binarySearchTime = binarySearchTime;
        }
    }

    public static Result solveAll(int k, int n) {
        // Measure DP approach time
        long startTime = System.nanoTime();
