import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

class SecurePaymentProcessor {
    private static final char[] HEX_TABLE = "0123456789ABCDEF".toCharArray();

    public String generateSecurePaymentUrl(String baseUrl, String secret, Map<String, String> parameters) {
        // Input validation
        if (baseUrl == null || baseUrl.isEmpty()) {
            throw new IllegalArgumentException("Base URL cannot be null or empty");
        }

        if (secret == null || secret.isEmpty()) {
            throw new IllegalArgumentException("Secret cannot be null or empty");
        }

        if (parameters == null || parameters.isEmpty()) {
            return baseUrl;
        }

        StringBuilder urlBuilder = new StringBuilder(baseUrl);

        // Sort parameters by key
        List<String> sortedKeys = new ArrayList<>(parameters.keySet());
        Collections.sort(sortedKeys);

        // Append parameters
        boolean firstParam = true;
        for (String key : sortedKeys) {
            String value = parameters.get(key);

            // Add separator
            if (firstParam) {
                urlBuilder.append("?");
                firstParam = false;
            } else {
                urlBuilder.append("&");
            }

            // Append key-value pair with URL encoding
            try {
                urlBuilder.append(URLEncoder.encode(key, "UTF-8"))
                          .append("=")
                          .append(URLEncoder.encode(value, "UTF-8"));
            } catch (UnsupportedEncodingException e) {
                // This should never happen as UTF-8 is always supported
                throw new RuntimeException("UTF-8 encoding not supported", e);
            }
        }

        return urlBuilder.toString();
    }

    private String generateSecureHash(String secret, Map<String, String> parameters) {
        try {
            // Create MD5 message digest
            MessageDigest md = MessageDigest.getInstance("MD5");

            // Start with the secret
            StringBuilder dataToHash = new StringBuilder(secret);

            // Sort parameters by key
            List<String> sortedKeys = new ArrayList<>(parameters.keySet());
            Collections.sort(sortedKeys);

            // Append all non-empty parameter values in sorted order
            for (String key : sortedKeys) {
                String value = parameters.get(key);
                if (value != null && !value.isEmpty()) {
                    dataToHash.append(value);
                }
            }

            // Generate hash
            byte[] hashBytes = md.digest(dataToHash.toString().getBytes("UTF-8"));

            // Convert to hexadecimal string
            return bytesToHex(hashBytes);
        } catch (NoSuchAlgorithmException | UnsupportedEncodingException e) {
            throw new RuntimeException("Error generating secure hash", e);
        }
    }

    private String bytesToHex(byte[] bytes) {
        char[] hexChars = new char[bytes.length * 2];
        for (int i = 0; i < bytes.length; i++) {
            int v = bytes[i] & 0xFF;
            hexChars[i * 2] = HEX_TABLE[v >>> 4];
            hexChars[i * 2 + 1] = HEX_TABLE[v & 0x0F];
        }
        return new String(hexChars);
    }
}

