import java.util.*;
import java.net.URLEncoder;
import java.io.UnsupportedEncodingException;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;

class SecurePaymentProcessor {

    public String generateSecurePaymentUrl(String baseUrl, Map<String, String> params, String secret) {
        // Validate secret
        if (secret == null || secret.isEmpty()) {
            throw new IllegalArgumentException("Secret key must not be null or empty");
        }

        // Create a copy of params to avoid modifying the original map
        Map<String, String> paramsCopy = new HashMap<>(params);

        // Generate secure hash
        String secureHash = generateSecureHash(paramsCopy, secret);

        // Add the secure hash to parameters
        paramsCopy.put("vpc_SecureHash", secureHash);

        // Build URL with all parameters including the hash
        return buildUrlWithParameters(baseUrl, paramsCopy);
    }

    private String generateSecureHash(Map<String, String> params, String secret) {
        try {
            // Sort parameters by key
            List<String> sortedKeys = new ArrayList<>(params.keySet());
            Collections.sort(sortedKeys);

            // Build query string
            StringBuilder queryString = new StringBuilder();
            boolean first = true;
            for (String key : sortedKeys) {
                String value = params.get(key);
                if (value != null && !value.isEmpty()) {
                    if (!first) {
                        queryString.append("&");
                    }
                    queryString.append(key).append("=").append(value);
                    first = false;
                }
            }

            // Generate HMAC-SHA256 hash
            Mac mac = Mac.getInstance("HmacSHA256");
            SecretKeySpec secretKeySpec = new SecretKeySpec(secret.getBytes("UTF-8"), "HmacSHA256");
            mac.init(secretKeySpec);

            byte[] hashBytes = mac.doFinal(queryString.toString().getBytes("UTF-8"));

            // Convert to hexadecimal string
            StringBuilder hexString = new StringBuilder();
            for (byte b : hashBytes) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) {
                    hexString.append('0');
                }
                hexString.append(hex);
            }

            return hexString.toString().toUpperCase();
        } catch (NoSuchAlgorithmException | InvalidKeyException | UnsupportedEncodingException e) {
            throw new RuntimeException("Failed to generate secure hash: " + e.getMessage(), e);
