import java.util.HashMap;
import java.util.Map;

public class AlertingService {
    private Map<String, Integer> alertCounts;
    private Map<String, String> lastAlertMessages;

    public AlertingService() {
        alertCounts = new HashMap<>();
        lastAlertMessages = new HashMap<>();
    }

    public void triggerAlert(String severityLevel, String message) {
        // Increment alert count for the severity level
        alertCounts.put(severityLevel, alertCounts.getOrDefault(severityLevel, 0) + 1);

        // Update the last alert message for the severity level
        lastAlertMessages.put(severityLevel, message);
    }

    public int getAlertCount(String severityLevel) {
        return alertCounts.getOrDefault(severityLevel, 0);
    }

    public String getLastAlertMessage(String severityLevel) {
        return lastAlertMessages.get(severityLevel);
    }

    public void resetStatistics() {
        alertCounts.clear();
        lastAlertMessages.clear();
    }
}

