public class EnhancedTestUtils {

    /**
     * Creates a list of specified count by using a supplier function.
     * 
     * @param <T> the type of elements generated by the supplier
     * @param <R> the type of elements in the result list
     * @param count the number of elements to generate (must be non-negative)
     * @param supplier the supplier function to generate elements (must not be null)
     * @param validator the optional validator function to validate each element
     * @param transformer the optional transformer function to transform each element
     * @return a list containing the generated and optionally transformed elements
     * @throws IllegalArgumentException if count is negative or supplier is null
     * @throws RuntimeException if validator throws a RuntimeException
     */
    public static <T, R> List<R> createEnhancedList(int count, Supplier<T> supplier, Consumer<T> validator, Function<T, R> transformer) {
        // Validate that count is non-negative
        if (count < 0) {
            throw new IllegalArgumentException("Count must be non-negative");
        }

        // Validate that supplier is not null
        Objects.requireNonNull(supplier, "Supplier must not be null");

        // Create the list and populate it using the supplier
        List<R> result = new ArrayList<>(count);
        for (int i = 0; i < count; i++) {
            T element = supplier.get();

            // If validator is provided, invoke it and wrap any RuntimeException
            if (validator != null) {
                try {
                    validator.accept(element);
                } catch (RuntimeException e) {
                    throw new RuntimeException("Validation failed for element: " + element, e);
                }
            }

            // If transformer is provided, apply it; otherwise, cast/assign the original element
            R transformedElement = (transformer != null) ? transformer.apply(element) : (R) element;
            result.add(transformedElement);
        }

        return result;
    }

    // Overloaded method with transformer but no validator
    public static <T, R> List<R> createEnhancedList(int count, Supplier<T> supplier, Function<T, R> transformer) {
        return createEnhancedList(count, supplier, null, transformer);
    }

    // Overloaded method with validator but no transformer
    public static <T> List<T> createEnhancedList(int count, Supplier<T> supplier, Consumer<T> validator) {
        return createEnhancedList(count, supplier, validator, null);
    }

    // Overloaded method with neither validator nor transformer
    public static <T> List<T> createEnhancedList(int count, Supplier<T> supplier) {
        return createEnhancedList(count, supplier, null, null);
    }
