import java.util.HashMap;
import java.util.Map;

public class ServerApprovalHandler {
    private String serverName;
    private String serverIp;
    private String realmId;
    private String imageId;
    private String hardwareProfileId;
    private Map<String, String> approvalStatus;

    public ServerApprovalHandler(String serverName, String serverIp, String realmId, 
                                String imageId, String hardwareProfileId) {
        this.serverName = serverName;
        this.serverIp = serverIp;
        this.realmId = realmId;
        this.imageId = imageId;
        this.hardwareProfileId = hardwareProfileId;
        this.approvalStatus = new HashMap<>();
        this.approvalStatus.put("status", "pending");
    }

    public Map<String, Object> validateConfiguration() {
        Map<String, Object> validationResult = new HashMap<>();

        // Validate server name
        if (serverName == null || serverName.trim().isEmpty()) {
            validationResult.put("serverName", "Invalid: Server name is required");
        } else {
            validationResult.put("serverName", "Valid");
        }

        // Validate IP address format
        if (serverIp == null || !isValidIpAddress(serverIp)) {
            validationResult.put("serverIp", "Invalid: IP address format is incorrect");
        } else {
            validationResult.put("serverIp", "Valid");
        }

        // Validate realm ID
        if (realmId == null || realmId.trim().isEmpty()) {
            validationResult.put("realmId", "Invalid: Realm ID is required");
        } else {
            validationResult.put("realmId", "Valid");
        }

        // Validate image ID
        if (imageId == null || imageId.trim().isEmpty()) {
            validationResult.put("imageId", "Invalid: Image ID is required");
        } else {
            validationResult.put("imageId", "Valid");
        }

        // Validate hardware profile ID
        if (hardwareProfileId == null || hardwareProfileId.trim().isEmpty()) {
            validationResult.put("hardwareProfileId", "Invalid: Hardware profile ID is required");
        } else {
            validationResult.put("hardwareProfileId", "Valid");
        }

        return validationResult;
    }

    private boolean isValidIpAddress(String ip) {
        if (ip == null || ip.isEmpty()) {
            return false;
        }

        String[] parts = ip.split("\\.");
        if (parts.length != 4) {
            return false;
        }

        for (String part : parts) {
            try {
                int num = Integer.parseInt(part);
                if (num < 0 || num > 255) {
                    return false;
                }
            } catch (NumberFormatException e) {
                return false;
            }
        }

        return true;
    }

    public Map<String, Object> processApproval() {
        Map<String, Object> result = new HashMap<>();

        // Get validation results
        Map<String, Object> validationResults = validateConfiguration();

        // Check if all validations passed
        boolean allValid = validationResults.values().stream()
                .allMatch(value -> "Valid".equals(value));

        if (allValid) {
            approvalStatus.put("status", "approved");
            result.put("approvalStatus", "approved");
            result.put("message", "Server configuration approved successfully");
        } else {
            approvalStatus.put("status", "rejected");
            result.put("approvalStatus", "rejected");
            result.put("message", "Server configuration rejected due to validation errors");
        }

        result.put("validationResults", validationResults);
        return result;
    }

    // Getters for the fields
    public String getServerName() {
        return serverName;
    }

    public String getServerIp() {
        return serverIp;
    }

    public String getRealmId() {
        return realmId;
    }

    public String getImageId() {
        return imageId;
    }

    public String getHardwareProfileId() {
        return hardwareProfileId;
    }

    public Map<String, String> getApprovalStatus() {
        return approvalStatus;
    }
}

