import java.util.*;

class GraphAnalyzer {
    private Map<String, List<Edge>> adjacencyList;
    private boolean directed;
    private boolean weighted;

    public GraphAnalyzer(boolean directed, boolean weighted) {
        this.adjacencyList = new HashMap<>();
        this.directed = directed;
        this.weighted = weighted;
    }

    public void addNode(String node) {
        if (!adjacencyList.containsKey(node)) {
            adjacencyList.put(node, new ArrayList<>());
        }
    }

    public void addEdge(String from, String to, int weight) {
        // Add nodes if they don't exist
        addNode(from);
        addNode(to);

        // Add edge from 'from' to 'to'
        adjacencyList.get(from).add(new Edge(to, weight));

        // If undirected, also add edge from 'to' to 'from'
        if (!directed) {
            adjacencyList.get(to).add(new Edge(from, weight));
        }
    }

    // Overloaded method for unweighted graphs
    public void addEdge(String from, String to) {
        addEdge(from, to, 1);
    }

    public int getNodeDegree(String node) {
        if (!adjacencyList.containsKey(node)) {
            throw new IllegalArgumentException("Node does not exist in the graph");
        }

        if (directed) {
            // For directed graphs, we need to count both incoming and outgoing edges
            int outgoingEdges = adjacencyList.get(node).size();
            int incomingEdges = 0;

            // Count incoming edges by checking all other nodes' adjacency lists
            for (List<Edge> edges : adjacencyList.values()) {
                for (Edge edge : edges) {
                    if (edge.destination.equals(node)) {
                        incomingEdges++;
                    }
                }
            }

            return outgoingEdges + incomingEdges;
        } else {
            // For undirected graphs, just return the size of adjacency list
            return adjacencyList.get(node).size();
        }
    }

    public boolean hasCycle() {
        Set<String> visited = new HashSet<>();

        // Check for cycle in each component of the graph
        for (String node : adjacencyList.keySet()) {
            if (!visited.contains(node)) {
                if (directed) {
                    if (hasCycleDirected(node, visited, new HashSet<>())) {
                        return true;
                    }
                } else {
                    if (hasCycleUndirected(node, visited, null)) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    private boolean hasCycleDirected(String node, Set<String> visited, Set<String> recursionStack) {
        // Mark the current node as visited and add to recursion stack
        visited.add(node);
        recursionStack.add(node);

        // Check all neighbors
        for (Edge edge : adjacencyList.get(node)) {
            String neighbor = edge.destination;

            // If neighbor is not visited, recursively check for cycle
            if (!visited.contains(neighbor)) {
                if (hasCycleDirected(neighbor, visited, recursionStack)) {
                    return true;
                }
            } 
            // If neighbor is in recursion stack, we found a cycle
            else if (recursionStack.contains(neighbor)) {
                return true;
            }
        }

        // Remove from recursion stack
        recursionStack.remove(node);
        return false;
    }

    private boolean hasCycleUndirected(String node, Set<String> visited, String parent) {
        // Mark the current node as visited
        visited.add(node);

        // Check all neighbors
        for (Edge edge : adjacencyList.get(node)) {
            String neighbor = edge.destination;

            // If neighbor is not visited, recursively check for cycle
            if (!visited.contains(neighbor)) {
                if (hasCycleUndirected(neighbor, visited, node)) {
                    return true;
                }
            } 
            // If neighbor is visited and not parent, we found a cycle
            else if (!neighbor.equals(parent)) {
                return true;
            }
        }

        return false;
    }

    static class Edge {
        String destination;
        int weight;

        public Edge(String destination, int weight) {
            this.destination = destination;
            this.weight = weight;
        }
    }
}

