import java.util.*;

public class CourseScheduler {

    public static class Result {
        public final boolean canFinish;
        public final int[] order;

        public Result(boolean canFinish, int[] order) {
            this.canFinish = canFinish;
            this.order = order;
        }
    }

    public Result scheduleCourses(int numCourses, int[][] prerequisites) {
        // Build adjacency list representation of the graph
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < numCourses; i++) {
            graph.add(new ArrayList<>());
        }

        // Calculate in-degrees for each course
        int[] inDegree = new int[numCourses];

        // Process prerequisites to build graph and calculate in-degrees
        for (int[] prerequisite : prerequisites) {
            int course = prerequisite[0];
            int prerequisiteCourse = prerequisite[1];
            // prerequisiteCourse -> course (prerequisiteCourse is a prerequisite for course)
            graph.get(prerequisiteCourse).add(course);
            inDegree[course]++;
        }

        // Find courses with no prerequisites (in-degree = 0)
        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i < numCourses; i++) {
            if (inDegree[i] == 0) {
                queue.offer(i);
            }
        }

        // Perform topological sort using Kahn's algorithm
        int[] order = new int[numCourses];
        int index = 0;

        while (!queue.isEmpty()) {
            int currentCourse = queue.poll();
            order[index++] = currentCourse;

            // Reduce in-degree for all dependent courses
            for (int nextCourse : graph.get(currentCourse)) {
                inDegree[nextCourse]--;
                // If in-degree becomes 0, add to queue
                if (inDegree[nextCourse] == 0) {
                    queue.offer(nextCourse);
                }
            }
        }

        // Check if all courses can be finished (no cycles)
        boolean canFinish = index == numCourses;

        // If there's a cycle, return empty order array
        if (!canFinish) {
            return new Result(false, new int[0]);
        }

        return new Result(canFinish, order);
    }
}
