import java.util.*;

public class BracketValidator {
    public static Map<String, Object> validateBrackets(String input) {
        Map<String, Object> result = new HashMap<>();
        Stack<Integer> stack = new Stack<>(); // Store indices of opening brackets
        result.put("balanced", true);
        result.put("errorPosition", -1);
        result.put("errorType", "");

        // Define matching pairs
        Map<Character, Character> bracketPairs = new HashMap<>();
        bracketPairs.put(')', '(');
        bracketPairs.put(']', '[');
        bracketPairs.put('}', '{');

        // Define opening brackets for quick lookup
        Set<Character> openingBrackets = new HashSet<>(Arrays.asList('(', '[', '{'));
        // Define closing brackets for quick lookup
        Set<Character> closingBrackets = new HashSet<>(Arrays.asList(')', ']', '}'));

        if (input != null) {
            char[] chars = input.toCharArray();
            for (int i = 0; i < chars.length; i++) {
                char c = chars[i];
                // Only process bracket characters
                if (openingBrackets.contains(c)) {
                    stack.push(i); // Push the index of opening bracket
                } else if (closingBrackets.contains(c)) {
                    // If stack is empty - closing bracket without matching opening
                    if (stack.isEmpty()) {
                        result.put("balanced", false);
                        result.put("errorPosition", i);
                        result.put("errorType", "mismatch");
                        return result;
                    }
                    // Check if brackets match
                    int openingIndex = stack.pop();
                    char openingBracket = chars[openingIndex];
                    if (openingBracket != bracketPairs.get(c)) {
                        result.put("balanced", false);
                        result.put("errorPosition", i);
                        result.put("errorType", "mismatch");
                        return result;
                    }
                }
            }

            // If stack is not empty, there are unclosed opening brackets
            if (!stack.isEmpty()) {
                result.put("balanced", false);
                result.put("errorPosition", stack.peek()); // First unclosed opening bracket
                result.put("errorType", "unclosed");
                return result;
            }
        }

        return result;
    }
}

