class PermissionInfo {
    private String uri;
    private String method;

    public PermissionInfo(String uri, String method) {
        this.uri = uri;
        this.method = method;
    }

    public String getUri() {
        return uri;
    }

    public String getMethod() {
        return method;
    }

    @Override
    public String toString() {
        return "PermissionInfo{uri='" + uri + "', method='" + method + "'}";
    }
}

class PermissionValidator {
    public boolean hasPermission(List<PermissionInfo> permissions, String requestUri, String requestMethod) {
        if (permissions == null || permissions.isEmpty()) {
            return false;
        }

        for (PermissionInfo permission : permissions) {
            if (permission != null && 
                matchesUri(permission.getUri(), requestUri) && 
                permission.getMethod().equalsIgnoreCase(requestMethod)) {
                return true;
            }
        }

        return false;
    }

    private boolean matchesUri(String permissionUri, String requestUri) {
        // Handle exact match first
        if (permissionUri.equals(requestUri)) {
            return true;
        }

        // Check if permission URI contains wildcard
        if (!permissionUri.contains("{*}")) {
            return false;
        }

        // Split both URIs into segments
        String[] permissionSegments = permissionUri.split("/");
        String[] requestSegments = requestUri.split("/");

        // If segment counts don't match, no match possible
        if (permissionSegments.length != requestSegments.length) {
            return false;
        }

        // Check each segment
        for (int i = 0; i < permissionSegments.length; i++) {
            if ("{*}".equals(permissionSegments[i])) {
                // Wildcard segment must match exactly one non-empty alphanumeric segment
                if (requestSegments[i].isEmpty() || !isAlphanumeric(requestSegments[i])) {
                    return false;
                }
            } else if (!permissionSegments[i].equals(requestSegments[i])) {
                // Non-wildcard segments must match exactly
                return false;
            }
        }

        return true;
    }

    private boolean isAlphanumeric(String str) {
        if (str == null || str.isEmpty()) {
            return false;
        }

        for (int i = 0; i < str.length(); i++) {
            char c = str.charAt(i);
            if (!Character.isLetterOrDigit(c)) {
                return false;
            }
        }

        return true;
    }
}

