        return false;
    }

    private boolean matchesUri(String permissionUri, String requestUri) {
        // Handle exact match first
        if (permissionUri.equals(requestUri)) {
            return true;
        }

        // Check if permission URI contains wildcard
        if (permissionUri.contains("{*}")) {
            return matchesWildcardUri(permissionUri, requestUri);
        }

        // Handle prefix matching (only if no wildcard is present)
        return matchesPrefixUri(permissionUri, requestUri);
    }

    private boolean matchesWildcardUri(String permissionUri, String requestUri) {
        // Split both URIs into segments
        String[] permissionSegments = permissionUri.split("/");
        String[] requestSegments = requestUri.split("/");

