    private final ReentrantLock lock;
    private final Condition condition;
    private boolean isSignalled;

    public ThreadSynchronizer() {
        lock = new ReentrantLock();
        condition = lock.newCondition();
        isSignalled = false;
    }

    public boolean waitWithDeadline(int waitSeconds) {
        lock.lock();
        try {
            if (isSignalled) {
                return true;
            }

            Date deadline = new Date(System.currentTimeMillis() + waitSeconds * 1000L);
            return condition.awaitUntil(deadline);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return false;
        } finally {
            try {
                isSignalled = false;
            } finally {
                lock.unlock();
            }
        }
    }

    public void notifyAllThreads() {
        lock.lock();
        try {
            isSignalled = true;
            condition.signalAll();
        } finally {
            lock.unlock();
        }
    }
}
