import java.util.*;

class ScenarioAnalyzer {
    static class TreeNode {
        String name;
        String serverName;
        boolean isSync;
        List<TreeNode> children;
        TreeNode parent;

        TreeNode(String name, String serverName, boolean isSync) {
            this.name = name;
            this.serverName = serverName;
            this.isSync = isSync;
            this.children = new ArrayList<>();
            this.parent = null;
        }
    }

    public Map<String, Object> analyzeScenario(TreeNode root) {
        Map<String, Object> result = new HashMap<>();
        Map<String, Integer> nodeIndices = new HashMap<>();
        Map<Integer, Integer> syncPairs = new HashMap<>();

        if (root == null) {
            result.put("nodeIndices", nodeIndices);
            result.put("syncPairs", syncPairs);
            return result;
        }

        // First pass: assign indices using BFS
        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);
        int index = 0;
        List<TreeNode> nodesInOrder = new ArrayList<>();

        while (!queue.isEmpty()) {
            TreeNode current = queue.poll();
            nodeIndices.put(current.name, index++);
            nodesInOrder.add(current);

            for (TreeNode child : current.children) {
                child.parent = current; // Set parent reference
                queue.offer(child);
            }
        }

        // Second pass: detect synchronous pairs
        for (int i = 0; i < nodesInOrder.size(); i++) {
            TreeNode node = nodesInOrder.get(i);
            if (node.isSync && node.parent != null) {
                String requestServer = node.parent.serverName;

                // Look for response node among children
                for (TreeNode child : node.children) {
                    if (child.serverName != null && child.serverName.equals(requestServer)) {
                        syncPairs.put(i, nodeIndices.get(child.name));
                        break;
                    }
                }
            }
        }

        result.put("nodeIndices", nodeIndices);
        result.put("syncPairs", syncPairs);
        return result;
    }
}

