    public Map<String, Object> analyzeScenario(TreeNode root) {
        Map<String, Object> result = new HashMap<>();
        Map<String, Integer> nodeIndices = new HashMap<>();
        Map<Integer, List<Integer>> syncPairs = new HashMap<>();
        List<String> warnings = new ArrayList<>();

        if (root == null) {
            result.put("nodeIndices", nodeIndices);
            result.put("syncPairs", syncPairs);
            result.put("warnings", warnings);
            return result;
        }

        // First pass: assign indices using BFS
        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);
        int index = 0;
        List<TreeNode> nodesInOrder = new ArrayList<>();

        while (!queue.isEmpty()) {
            TreeNode current = queue.poll();
            nodeIndices.put(current.name, index++);
            nodesInOrder.add(current);

            for (TreeNode child : current.children) {
                child.parent = current; // Set parent reference
                queue.offer(child);
            }
        }

        // Second pass: detect synchronous pairs and generate warnings
        for (int i = 0; i < nodesInOrder.size(); i++) {
            TreeNode node = nodesInOrder.get(i);
            if (node.isSync && node.parent != null) {
                String requestServer = node.parent.serverName;
                String responseServer = node.serverName;
                boolean hasResponse = false;

                // Look for all response nodes among children
                for (TreeNode child : node.children) {
                    if (child.serverName != null && child.serverName.equals(requestServer)) {
                        // Initialize list if it doesn't exist
                        syncPairs.computeIfAbsent(i, k -> new ArrayList<>());
                        // Add response index to the list
                        syncPairs.get(i).add(nodeIndices.get(child.name));
                        hasResponse = true;
                    }
                }

                // Generate warning if no response found
                if (!hasResponse) {
                    warnings.add("Warning: There is no corresponding response to server \"" + 
                               requestServer + "\" from server \"" + responseServer + "\"");
                }
            }
        }

        result.put("nodeIndices", nodeIndices);
        result.put("syncPairs", syncPairs);
        result.put("warnings", warnings);
        return result;
    }
}

