                } catch (Exception e) {
                    allStoppedSuccessfully = false;
                }
            }

            return allStoppedSuccessfully;
        } finally {
            // Reset the shutdown flag when complete
            isShuttingDown.set(false);
        }
    }

    public interface Service {
        void stop() throws Exception;
    }
}

