import java.util.ArrayList;
import java.util.List;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;

class WebServiceClient {
    public List<String> getPagedResults(String baseUrl, String endpoint, String whereClause, 
                                      int firstResult, int maxResults) throws Exception {
        // Construct URL using the provided parameters
        StringBuilder urlBuilder = new StringBuilder();

        // Ensure baseUrl ends with a slash
        if (!baseUrl.endsWith("/")) {
            urlBuilder.append(baseUrl).append("/");
        } else {
            urlBuilder.append(baseUrl);
        }

        // Add endpoint
        urlBuilder.append(endpoint);

        // Add query parameters
        urlBuilder.append("?firstResult=").append(firstResult);
        urlBuilder.append("&maxResults=").append(maxResults);

        // Add where clause if provided
        if (whereClause != null && !whereClause.isEmpty()) {
            urlBuilder.append("&where=").append(URLEncoder.encode(whereClause, StandardCharsets.UTF_8.toString()));
        }

        // Build the full URL
        String fullUrl = urlBuilder.toString();

        // Call simulateHttpRequest with the full URL
        String response = simulateHttpRequest(fullUrl);

        // Pass the response to parseResponseItems for extraction
        return parseResponseItems(response);
    }

    private String simulateHttpRequest(String urlString) {
        if (urlString.contains("/schema")) {
            return "<xs:element name=\"Openbravo\">";
        } else if (urlString.contains("/dal") && urlString.contains("ADColumn")) {
            // Parse firstResult and maxResults from URL
            int firstResult = 0;
            int maxResults = 50;

            // Extract query parameters
            String[] parts = urlString.split("\\?");
            if (parts.length > 1) {
                String[] params = parts[1].split("&");
                for (String param : params) {
                    if (param.startsWith("firstResult=")) {
                        firstResult = Integer.parseInt(param.substring(12));
                    } else if (param.startsWith("maxResults=")) {
                        maxResults = Integer.parseInt(param.substring(11));
                    }
                }
            }

            // Generate simulated XML response
            StringBuilder response = new StringBuilder();
            response.append("<ADColumnResponse>");

            // Generate up to maxResults items, starting from firstResult
            int itemsToGenerate = Math.min(maxResults, 50);
            for (int i = 0; i < itemsToGenerate; i++) {
                int id = firstResult + i;
                response.append("<ADColumn id=\"").append(id).append("\">Column").append(id).append("</ADColumn>");
            }

            response.append("</ADColumnResponse>");
            return response.toString();
        } else if (urlString.contains("/dal")) {
            return "<Types>";
        } else {
            throw new RuntimeException("Unknown endpoint: " + urlString);
        }
    }

    private List<String> parseResponseItems(String response) {
        List<String> items = new ArrayList<>();

        int startIndex = 0;
        while (true) {
            // Find the start of an ADColumn tag
            int startTagIndex = response.indexOf("<ADColumn", startIndex);
            if (startTagIndex == -1) {
                break; // No more ADColumn tags found
            }

            // Find the end of the corresponding closing tag
            int endTagIndex = response.indexOf("</ADColumn>", startTagIndex);
            if (endTagIndex == -1) {
                break; // Malformed XML, no closing tag found
            }

            // Extract the complete ADColumn element (including both opening and closing tags)
            String item = response.substring(startTagIndex, endTagIndex + 11); // +11 for "</ADColumn>"
            items.add(item);

            // Move the start index past this element for the next iteration
            startIndex = endTagIndex + 11;
        }

        return items;
    }
}
