import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionException;
import java.util.concurrent.TimeUnit;
import java.util.function.Supplier;

class AsyncOperationManager {

    public <T> CompletableFuture<T> executeWithTimeoutAndRetry(
            Supplier<T> taskSupplier,
            long timeout,
            TimeUnit timeUnit,
            T fallbackValue,
            int maxRetries) {
        return retryTask(taskSupplier, timeout, timeUnit, fallbackValue, maxRetries, 0);
    }

    private <T> CompletableFuture<T> retryTask(
            Supplier<T> taskSupplier,
            long timeout,
            TimeUnit timeUnit,
            T fallbackValue,
            int maxRetries,
            int currentAttempt) {

        return CompletableFuture.supplyAsync(taskSupplier)
                .orTimeout(timeout, timeUnit)
                .exceptionally(throwable -> fallbackValue)
                .thenCompose(result -> {
                    // If we got the fallback value and we have retries left, attempt retry
                    if (result.equals(fallbackValue) && currentAttempt < maxRetries) {
                        // Delay before retry
                        return CompletableFuture.runAsync(() -> {
                            try {
                                Thread.sleep(500);
                            } catch (InterruptedException e) {
                                throw new CompletionException(e);
                            }
                        }).thenCompose(voidResult -> 
                            retryTask(taskSupplier, timeout, timeUnit, fallbackValue, maxRetries, currentAttempt + 1)
                        );
                    } else {
                        return CompletableFuture.completedFuture(result);
                    }
                });
    }
}

