import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionException;
import java.util.concurrent.TimeUnit;
import java.util.function.Supplier;

class AsyncOperationManager {

    public <T> CompletableFuture<T> executeWithTimeoutAndRetry(
            Supplier<T> taskSupplier,
            long timeout,
            TimeUnit timeUnit,
            T fallbackValue,
            int maxRetries) {
        return retryTask(taskSupplier, timeout, timeUnit, fallbackValue, maxRetries, 0, null);
    }

    private <T> CompletableFuture<T> retryTask(
            Supplier<T> taskSupplier,
            long timeout,
            TimeUnit timeUnit,
            T fallbackValue,
            int maxRetries,
            int currentAttempt,
            Throwable lastException) {

        return CompletableFuture.supplyAsync(taskSupplier)
                .orTimeout(timeout, timeUnit)
                .handle((result, throwable) -> {
                    if (throwable != null) {
                        // Task failed with exception
                        return CompletableFuture.completedFuture(
                            new RetryResult<T>(null, throwable));
                    } else if (result == null || result.equals(fallbackValue)) {
                        // Task timed out (returned fallbackValue)
                        return CompletableFuture.completedFuture(
                            new RetryResult<T>(fallbackValue, null));
                    } else {
                        // Task succeeded
                        return CompletableFuture.completedFuture(
                            new RetryResult<T>(result, null));
                    }
                })
                .thenCompose(completedFuture -> completedFuture)
                .thenCompose(retryResult -> {
                    // If task succeeded, return the result
                    if (retryResult.exception == null && 
                        retryResult.result != null && 
                        !retryResult.result.equals(fallbackValue)) {
                        return CompletableFuture.completedFuture(retryResult.result);
                    }

                    // If we've exhausted all retries
                    if (currentAttempt >= maxRetries) {
                        if (retryResult.result != null && retryResult.result.equals(fallbackValue)) {
                            // All attempts timed out, return fallback
                            return CompletableFuture.completedFuture(fallbackValue);
                        } else {
                            // All attempts failed with exceptions, throw the last one
                            return CompletableFuture.failedFuture(retryResult.exception);
                        }
                    }

                    // Delay before retry
                    return CompletableFuture.runAsync(() -> {
                        try {
                            Thread.sleep(500);
                        } catch (InterruptedException e) {
                            throw new CompletionException(e);
                        }
                    }).thenCompose(voidResult -> 
                        retryTask(taskSupplier, timeout, timeUnit, fallbackValue, maxRetries, currentAttempt + 1, retryResult.exception)
                    );
                });
    }

    private static class RetryResult<T> {
        final T result;
        final Throwable exception;

        RetryResult(T result, Throwable exception) {
            this.result = result;
            this.exception = exception;
        }
    }
}

