import java.util.*;

public class TreePathAnalyzer {

    public static class Node {
        int data;
        List<Node> children;

        public Node(int data) {
            this.data = data;
            this.children = new ArrayList<>();
        }

        public void addChild(Node child) {
            this.children.add(child);
        }

        @Override
        public String toString() {
            return String.valueOf(data);
        }
    }

    private List<Node> globalLongestPath;

    public List<Node> findLongestPath(Node root) {
        if (root == null) {
            return new ArrayList<>();
        }

        globalLongestPath = new ArrayList<>();
        dfs(root);
        return new ArrayList<>(globalLongestPath);
    }

    private int dfs(Node node) {
        if (node == null) {
            return 0;
        }

        // Track the two longest paths from children
        int firstLongest = 0;
        int secondLongest = 0;
        Node firstChild = null;
        Node secondChild = null;

        // Process all children
        for (Node child : node.children) {
            int childDepth = dfs(child);

            if (childDepth > firstLongest) {
                secondLongest = firstLongest;
                secondChild = firstChild;
                firstLongest = childDepth;
                firstChild = child;
            } else if (childDepth > secondLongest) {
                secondLongest = childDepth;
                secondChild = child;
            }
        }

        // Update global longest path if path through current node is longer
        int currentPathLength = firstLongest + secondLongest + 1;
        if (currentPathLength > globalLongestPath.size()) {
            globalLongestPath.clear();

            // Build the path: second longest path + current node + first longest path
            List<Node> firstPath = getPathToLeaf(firstChild);
            List<Node> secondPath = getPathToLeaf(secondChild);

            // Add second path in reverse order
            for (int i = secondPath.size() - 1; i >= 0; i--) {
                globalLongestPath.add(secondPath.get(i));
            }

            // Add current node
            globalLongestPath.add(node);

            // Add first path
            globalLongestPath.addAll(firstPath);
        }

        // Return the longest depth from this node
        return firstLongest + 1;
    }

    private List<Node> getPathToLeaf(Node node) {
        List<Node> path = new ArrayList<>();
        if (node == null) {
            return path;
        }

        Node current = node;
        while (current != null) {
            path.add(current);
            Node next = null;
            int maxDepth = -1;

            // Find the child with maximum depth
            for (Node child : current.children) {
                int depth = getMaxDepth(child);
                if (depth > maxDepth) {
                    maxDepth = depth;
                    next = child;
                }
            }

            current = next;
        }

        return path;
    }

    private int getMaxDepth(Node node) {
        if (node == null) {
            return 0;
        }

        int maxDepth = 0;
        for (Node child : node.children) {
            maxDepth = Math.max(maxDepth, getMaxDepth(child));
        }

        return maxDepth + 1;
    }
}

