                case "vertical-tab":
                    pattern = "\\v";
                    description = "Vertical tab character";
                    break;
                case "null":
                    pattern = "\\0";
                    description = "Null character";
                    break;
                default:
                    throw new IllegalArgumentException("Unknown special character type: " + specialCharType);
            }
        } else {
            throw new IllegalArgumentException("Unknown pattern type: " + patternType);
        }

        // Validate the generated pattern
        try {
            Pattern.compile(pattern);
        } catch (PatternSyntaxException e) {
            throw new PatternSyntaxException("Invalid regex pattern generated: " + pattern, pattern, e.getIndex());
        }

        result.put("pattern", pattern);
