        tokenExpirationDatabase.put("user192.168.1.1", new Date(System.currentTimeMillis() + 3600000)); // 1 hour from now

        // Initialize token status database
        tokenStatusDatabase = new HashMap<>();
        tokenStatusDatabase.put("user192.168.1.1", 1); // 1 = active, anything else = inactive
    }

    public Map<String, Object> validateToken(String token, String clientIp) {
        Map<String, Object> result = new HashMap<>();
        if (token == null || token.isEmpty()) {
            result.put("valid", false);
