import java.util.*;

public class CelestialSimulator {

    public static class Vector {
        public double x;
        public double y;

        public Vector(double x, double y) {
            this.x = x;
            this.y = y;
        }

        public Vector add(Vector other) {
            return new Vector(this.x + other.x, this.y + other.y);
        }

        public Vector multiply(double scalar) {
            return new Vector(this.x * scalar, this.y * scalar);
        }

        public Vector divide(double scalar) {
            return new Vector(this.x / scalar, this.y / scalar);
        }
    }

    public static class Celestial {
        public String name;
        public double mass;
        public Vector position;
        public Vector velocity;
        public Vector acceleration;

        public Celestial(String name, double mass, Vector position, Vector velocity, Vector acceleration) {
            this.name = name;
            this.mass = mass;
            this.position = position;
            this.velocity = velocity;
            this.acceleration = acceleration;
        }

        // Create a copy of this celestial body
        public Celestial copy() {
            return new Celestial(
                this.name,
                this.mass,
                new Vector(this.position.x, this.position.y),
                new Vector(this.velocity.x, this.velocity.y),
                new Vector(this.acceleration.x, this.acceleration.y)
            );
        }
    }

    public static List<List<Celestial>> simulate(List<Celestial> bodies, double timeStep, int steps) {
        List<List<Celestial>> history = new ArrayList<>();

        // Add initial state to history
        List<Celestial> initialState = new ArrayList<>();
        for (Celestial body : bodies) {
            initialState.add(body.copy());
        }
        history.add(initialState);

        // Gravitational constant (arbitrary units for simulation)
        double G = 6.67430e-11;

        // Run simulation for the specified number of steps
        for (int step = 0; step < steps; step++) {
            // Calculate accelerations for all bodies
            for (int i = 0; i < bodies.size(); i++) {
                Celestial body1 = bodies.get(i);
                Vector totalForce = new Vector(0, 0);

                // Calculate gravitational force from all other bodies
                for (int j = 0; j < bodies.size(); j++) {
                    if (i != j) {
                        Celestial body2 = bodies.get(j);

                        // Calculate distance vector
                        double dx = body2.position.x - body1.position.x;
                        double dy = body2.position.y - body1.position.y;
                        double distance = Math.sqrt(dx * dx + dy * dy);

                        // Avoid division by zero
                        if (distance > 0) {
                            // Calculate gravitational force magnitude
                            double forceMagnitude = G * body1.mass * body2.mass / (distance * distance);

                            // Calculate force components
                            double fx = forceMagnitude * dx / distance;
                            double fy = forceMagnitude * dy / distance;

                            totalForce.x += fx;
                            totalForce.y += fy;
                        }
                    }
                }

                // Calculate acceleration (F = ma, so a = F/m)
                body1.acceleration = totalForce.divide(body1.mass);
            }

            // Update velocities and positions
            for (Celestial body : bodies) {
                // Update velocity: v = v0 + a * dt
                body.velocity = body.velocity.add(body.acceleration.multiply(timeStep));

                // Update position: x = x0 + v * dt
                body.position = body.position.add(body.velocity.multiply(timeStep));
            }

            // Add current state to history
            List<Celestial> currentState = new ArrayList<>();
            for (Celestial body : bodies) {
                currentState.add(body.copy());
            }
            history.add(currentState);
        }

        return history;
    }
}

