                new Vector(this.position.x, this.position.y),
                new Vector(this.velocity.x, this.velocity.y),
                new Vector(this.acceleration.x, this.acceleration.y)
            );
        }

        // Update method to update position and velocity using given time step
        public void update(double timeStep) {
            // Update position: x = x0 + v * t
            this.position = this.position.add(this.velocity.multiply(timeStep));

            // Update velocity: v = v0 + a * t
            this.velocity = this.velocity.add(this.acceleration.multiply(timeStep));
        }

        // Calculate gravitational force vector exerted by another celestial body
        public Vector calculateGravityForce(Celestial other) {
            // Gravitational constant
            double G = 6.67430e-11;

            // Calculate distance vector from this body to the other body
            Vector distanceVector = new Vector(
                other.position.x - this.position.x,
                other.position.y - this.position.y
            );

            // Calculate the distance magnitude
            double distance = distanceVector.magnitude();

            // Handle case where distance is extremely small to avoid division by zero
            // Use a small epsilon value to prevent numerical instability
            double epsilon = 1e-10;
            if (distance < epsilon) {
                return new Vector(0, 0);
