                node.right = new Node(element);
                size++;
                return true;
            } else {
                return add(node.right, element);
            }
        } else {
            return false;
        }
    }

    public boolean contains(T element) {
        return contains(root, element);
    }

    private boolean contains(Node node, T element) {
        if (node == null) return false;

        int cmp = element.compareTo(node.data);
        if (cmp < 0) {
            return contains(node.left, element);
        } else if (cmp > 0) {
            return contains(node.right, element);
        } else {
            return true;
        }
    }

    public T first() {
        if (root == null) {
            throw new NoSuchElementException("Tree is empty");
        }

        Node current = root;
        while (current.left != null) {
            current = current.left;
        }

        return current.data;
    }

    public T last() {
        if (root == null) {
            throw new NoSuchElementException("Tree is empty");
        }

        Node current = root;
        while (current.right != null) {
            current = current.right;
        }

        return current.data;
    }

    public boolean remove(T element) {
        if (element == null) {
            throw new NullPointerException("Cannot remove null elements");
        }

        int originalSize = size;
        root = remove(root, element);
        return size < originalSize;
    }

    private Node remove(Node node, T element) {
        if (node == null) {
            return null;
        }

        int cmp = element.compareTo(node.data);
        if (cmp < 0) {
            node.left = remove(node.left, element);
        } else if (cmp > 0) {
            node.right = remove(node.right, element);
        } else {
            // Node to be deleted found
            size--;

            // Case 1: Node has no children (leaf node)
            if (node.left == null && node.right == null) {
                return null;
            }
            // Case 2: Node has only one child
            else if (node.left == null) {
                return node.right;
            } else if (node.right == null) {
                return node.left;
            }
            // Case 3: Node has two children
            else {
                // Find the in-order successor (smallest node in right subtree)
                Node successor = findMin(node.right);
                // Replace current node's data with successor's data
                node.data = successor.data;
                // Remove the successor
                node.right = remove(node.right, successor.data);
                // Increment size back since we're not actually removing the original node
                size++;
            }
        }
        return node;
    }

    private Node findMin(Node node) {
        while (node.left != null) {
            node = node.left;
        }
        return node;
    }

    public boolean isEmpty() {
        return root == null;
    }

    public int size() {
        return size;
    }

    public void clear() {
        root = null;
        size = 0;
    }
}
