import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.HashSet;
import java.util.List;
import java.util.ArrayList;
import java.util.Properties;
import java.util.concurrent.TimeUnit;

public class ConfigurationManager {
    private Map<String, Object> configMap;
    private Set<String> requiredKeys;
    private Map<String, List<Validator>> validators;

    public ConfigurationManager(Set<String> requiredKeys, Map<String, List<Validator>> validators) {
        this.configMap = new HashMap<>();
        this.requiredKeys = requiredKeys != null ? new HashSet<>(requiredKeys) : new HashSet<>();
        this.validators = validators != null ? new HashMap<>(validators) : new HashMap<>();
    }

    public void setConfigValue(String key, Object value) {
        configMap.put(key, value);
    }

    @SuppressWarnings("unchecked")
    public <T> T getConfigValue(String key, Class<T> type) throws ConfigurationException {
        Object value = configMap.get(key);
        if (value == null) {
            return null;
        }

        if (type.isInstance(value)) {
            return (T) value;
        }

        // Handle type conversion
        if (value instanceof String) {
            String stringValue = (String) value;
            try {
                if (type == Integer.class || type == int.class) {
                    return (T) Integer.valueOf(stringValue);
                } else if (type == Long.class || type == long.class) {
                    return (T) Long.valueOf(stringValue);
                } else if (type == Double.class || type == double.class) {
                    return (T) Double.valueOf(stringValue);
                } else if (type == Boolean.class || type == boolean.class) {
                    return (T) Boolean.valueOf(stringValue);
                } else if (type == String.class) {
                    return (T) stringValue;
                } else if (type == TimeUnit.class) {
                    return (T) TimeUnit.valueOf(stringValue.toUpperCase());
                }
            } catch (Exception e) {
                throw new ConfigurationException("Failed to convert value '" + stringValue + "' to type " + type.getSimpleName());
            }
        }

        throw new ConfigurationException("Cannot convert value '" + value + "' to type " + type.getSimpleName());
    }

    public void loadConfiguration(Properties properties) throws ConfigurationException {
        if (properties == null) {
            properties = new Properties();
        }

        // Load properties into config map
        for (String key : properties.stringPropertyNames()) {
            configMap.put(key, properties.getProperty(key));
        }

        // Check for missing required keys
        Set<String> missingKeys = new HashSet<>();
        for (String requiredKey : requiredKeys) {
            if (!configMap.containsKey(requiredKey)) {
                missingKeys.add(requiredKey);
            }
        }

        if (!missingKeys.isEmpty()) {
            throw new ConfigurationException("Missing required keys: " + String.join(", ", missingKeys));
        }

        // Validate configuration
        validateConfiguration();
    }

    private void validateConfiguration() throws ConfigurationException {
        for (Map.Entry<String, List<Validator>> entry : validators.entrySet()) {
            String key = entry.getKey();
            List<Validator> keyValidators = entry.getValue();

            if (keyValidators != null && configMap.containsKey(key)) {
                Object value = configMap.get(key);
                for (Validator validator : keyValidators) {
                    if (!validator.isValid(value)) {
                        throw new ConfigurationException(validator.getErrorMessage());
                    }
                }
            }
        }
    }

    public static class ConfigurationException extends Exception {
        public ConfigurationException(String message) {
            super(message);
        }
    }

    public interface Validator {
        boolean isValid(Object value);
        String getErrorMessage();
    }
}

