import java.util.HashMap;
import java.util.Map;

public class UserAuthenticator {
    private Map<String, String> userDatabase;

    public UserAuthenticator() {
        userDatabase = new HashMap<>();
        // Hardcoded database with phone numbers and passwords
        userDatabase.put("1234567890", "password123");
        userDatabase.put("0987654321", "password456");
    }

    public AuthenticationResult authenticate(String phoneNumber, String password) {
        // Input validation
        if (phoneNumber == null) {
            throw new IllegalArgumentException("Phone number cannot be null");
        }

        if (phoneNumber.isEmpty()) {
            throw new IllegalArgumentException("Phone number cannot be empty");
        }

        if (password == null) {
            throw new IllegalArgumentException("Password cannot be null");
        }

        if (password.isEmpty()) {
            throw new IllegalArgumentException("Password cannot be empty");
        }

        if (phoneNumber.length() != 10) {
            throw new IllegalArgumentException("Phone number must be exactly 10 digits");
        }

        // Check if phone number exists in database
        if (userDatabase.containsKey(phoneNumber)) {
            // Check if password matches
            if (userDatabase.get(phoneNumber).equals(password)) {
                return new AuthenticationResult(200, "Authentication successful", phoneNumber);
            } else {
                return new AuthenticationResult(401, "Authentication failed: incorrect password", null);
            }
        } else {
            return new AuthenticationResult(404, "Authentication failed: phone number not found", null);
        }
    }

    public static class AuthenticationResult {
        private int statusCode;
        private String message;
        private String user;

        public AuthenticationResult(int statusCode, String message, String user) {
            this.statusCode = statusCode;
            this.message = message;
            this.user = user;
