import java.util.ArrayList;
import java.util.List;

class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;

    public TreeNode(int val) {
        this.val = val;
    }
}

class TreeAnalysisResult {
    List<List<Integer>> paths = new ArrayList<>();
    int maxDepth = 0;
    int leafCount = 0;
    boolean hasPathSum = false;

    @Override
    public String toString() {
        return "Paths: " + paths + "\n" +
               "Max Depth: " + maxDepth + "\n" +
               "Leaf Count: " + leafCount + "\n" +
               "Has Path Sum: " + hasPathSum;
    }
}

class TreePathAnalyzer {
    public TreeAnalysisResult analyzeTreePaths(TreeNode root, Integer targetSum) {
        TreeAnalysisResult result = new TreeAnalysisResult();
        if (root == null) {
            return result;
        }

        List<Integer> currentPath = new ArrayList<>();
        traverseTree(root, currentPath, result, targetSum, 1);

        return result;
    }

    private void traverseTree(TreeNode node, List<Integer> currentPath, 
                            TreeAnalysisResult result, Integer targetSum, int currentDepth) {
        if (node == null) {
            return;
        }

        currentPath.add(node.val);

        // Check if it's a leaf node
        if (node.left == null && node.right == null) {
            result.leafCount++;
            result.paths.add(new ArrayList<>(currentPath));

            // Update max depth when we reach a leaf node
            result.maxDepth = Math.max(result.maxDepth, currentDepth);

            // Check path sum if targetSum is provided
            if (targetSum != null) {
                int sum = 0;
                for (int val : currentPath) {
                    sum += val;
                }
                if (sum == targetSum) {
                    result.hasPathSum = true;
                }
            }
        }

        traverseTree(node.left, currentPath, result, targetSum, currentDepth + 1);
        traverseTree(node.right, currentPath, result, targetSum, currentDepth + 1);

        currentPath.remove(currentPath.size() - 1);
    }
}
