class PlayerInfo {
    private String playerId;
    private int score;

    public PlayerInfo(String playerId, int score) {
        this.playerId = playerId;
        this.score = score;
    }

    public String getPlayerId() {
        return playerId;
    }

    public int getScore() {
        return score;
    }

    public void setScore(int score) {
        this.score = score;
    }

    @Override
    public String toString() {
        return "PlayerInfo{playerId='" + playerId + "', score=" + score + "}";
    }
}

public class PlayerManagementSystem {
    private Map<String, PlayerInfo> players;

    public PlayerManagementSystem() {
        this.players = new HashMap<>();
    }

    public boolean registerPlayer(String playerId, int initialScore) {
        if (players.containsKey(playerId)) {
            return false; // Player already exists
        }
        players.put(playerId, new PlayerInfo(playerId, initialScore));
        return true; // Player successfully registered
    }

    public PlayerInfo getPlayer(String playerId) {
        return players.get(playerId);
    }

    public boolean updateScore(String playerId, int newScore) {
        PlayerInfo player = players.get(playerId);
        if (player != null) {
            player.setScore(newScore);
            return true;
        }
        return false;
    }

    public void displayAllPlayers() {
        for (PlayerInfo player : players.values()) {
            System.out.println(player);
        }
    }

    public static void main(String[] args) {
        PlayerManagementSystem system = new PlayerManagementSystem();

        // Test registration
        System.out.println("Registering players:");
        System.out.println("Player1: " + system.registerPlayer("player1", 100));
        System.out.println("Player2: " + system.registerPlayer("player2", 200));
        System.out.println("Player1 again: " + system.registerPlayer("player1", 150));

        System.out.println("\nAll players:");
        system.displayAllPlayers();
    }
}

