import java.util.concurrent.ConcurrentHashMap;
import java.util.Map;

class PlayerInfo {
    private String playerId;
    private int score;
    private boolean active;

    public PlayerInfo(String playerId, int score) {
        this.playerId = playerId;
        this.score = score;
        this.active = true;
    }

    public String getPlayerId() {
        return playerId;
    }

    public int getScore() {
        return score;
    }

    public void setScore(int score) {
        this.score = score;
    }

    public boolean isActive() {
        return active;
    }

    public void setActive(boolean active) {
        this.active = active;
    }

    @Override
    public String toString() {
        return "PlayerInfo{playerId='" + playerId + "', score=" + score + ", active=" + active + "}";
    }
}

public class PlayerManagementSystem {
    private final Map<String, PlayerInfo> players;

    public PlayerManagementSystem() {
        this.players = new ConcurrentHashMap<>();
    }

    public synchronized boolean registerPlayer(String playerId, int initialScore) {
        if (players.containsKey(playerId)) {
            return false; // Player already exists
        }
        players.put(playerId, new PlayerInfo(playerId, initialScore));
        return true; // Player successfully registered
    }

    public PlayerInfo getPlayer(String playerId) {
        return players.get(playerId);
    }

    public synchronized boolean updateScore(String playerId, int scoreChange) {
        PlayerInfo player = players.get(playerId);
        if (player != null && player.isActive()) {
            player.setScore(player.getScore() + scoreChange);
            return true;
        }
        return false;
    }

    public synchronized boolean removePlayer(String playerId) {
        PlayerInfo player = players.get(playerId);
        if (player != null) {
            player.setActive(false);
            players.remove(playerId);
            return true;
        }
        return false;
    }

    public void displayAllPlayers() {
        for (PlayerInfo player : players.values()) {
            System.out.println(player);
        }
    }

    public static void main(String[] args) {
        PlayerManagementSystem system = new PlayerManagementSystem();

        // Test registration
        System.out.println("Registering players:");
        System.out.println("Player1: " + system.registerPlayer("player1", 100));
        System.out.println("Player2: " + system.registerPlayer("player2", 200));
        System.out.println("Player1 again: " + system.registerPlayer("player1", 150));

        System.out.println("\nAll players:");
        system.displayAllPlayers();

        // Test score update
        System.out.println("\nUpdating scores:");
        System.out.println("Player1 +50: " + system.updateScore("player1", 50));
        System.out.println("Player2 -30: " + system.updateScore("player2", -30));
        System.out.println("Non-existent player: " + system.updateScore("player3", 10));

        System.out.println("\nAll players after score update:");
        system.displayAllPlayers();

        // Test removal
        System.out.println("\nRemoving players:");
        System.out.println("Remove Player1: " + system.removePlayer("player1"));
        System.out.println("Remove Player1 again: " + system.removePlayer("player1"));

        System.out.println("\nAll players after removal:");
        system.displayAllPlayers();
    }
}

