        for (PlayerInfo player : system.getRankings()) {
            System.out.println(player);
        }

        // Test output stream management
        PrintStream stream1 = System.out;
        PrintStream stream2 = System.err;

        system.addOutputStream(stream1);
        system.addOutputStream(stream2);

        System.out.println("\nOutput streams count: " + system.getOutputStreams().size());

        List<OutputStream> streamsCopy = system.getOutputStreams();
        System.out.println("Streams copy size: " + streamsCopy.size());

        system.removeOutputStream(stream1);
        System.out.println("After removing stream1, streams count: " + system.getOutputStreams().size());

