import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.atomic.AtomicInteger;

class FactorySimulation {
    private BlockingQueue<Item> inputStock;
    private BlockingQueue<Item> outputStock;
    private int totalItemsToProcess;
    private AtomicInteger processedItems;

    public FactorySimulation(int inputStockSize, int outputStockSize, int totalItemsToProcess) {
        this.inputStock = new LinkedBlockingQueue<>(inputStockSize);
        this.outputStock = new LinkedBlockingQueue<>(outputStockSize);
        this.totalItemsToProcess = totalItemsToProcess;
        this.processedItems = new AtomicInteger(0);
    }

    public void addToInputStock(Item item) throws InterruptedException {
        inputStock.put(item);
    }

    public Item takeFromOutputStock() throws InterruptedException {
        return outputStock.take();
    }

    public void startWorkshop() {
        Thread workshop = new Thread(() -> {
            try {
                while (processedItems.get() < totalItemsToProcess) {
                    // Take item from input stock
                    Item item = inputStock.take();

                    // Process the item (simulating work with sleep)
                    Thread.sleep(100); // Simulate processing time

                    // Move to output stock
                    outputStock.put(item);

                    // Increment processed count
                    processedItems.incrementAndGet();
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });

        workshop.start();
    }

    public int getProcessedItemsCount() {
        return processedItems.get();
    }

    public int getRemainingInputStock() {
        return inputStock.size();
    }

    public boolean isProcessingComplete() {
        return processedItems.get() >= totalItemsToProcess;
    }
}

class Item {
    private String id;

    public Item(String id) {
        this.id = id;
    }

    public String getId() {
        return id;
    }

    @Override
    public String toString() {
        return "Item{id='" + id + "'}";
    }
}

public class FactoryDemo {
    public static void main(String[] args) throws InterruptedException {
        // Create factory with input stock capacity 10, output stock capacity 10, process 5 items
        FactorySimulation factory = new FactorySimulation(10, 10, 5);

        // Add items to input stock
        for (int i = 1; i <= 8; i++) {
            factory.addToInputStock(new Item("ITEM-" + i));
