// Performance tracker class
class PerformanceTracker {
    private AtomicLong startTime;
    private AtomicLong endTime;
    private AtomicInteger processedItems;
    private AtomicInteger errors;
    private AtomicInteger inputStockFinalLevel;
    private AtomicInteger outputStockFinalLevel;
    private AtomicInteger intermediateStock1FinalLevel;
    private AtomicInteger intermediateStock2FinalLevel;

    public PerformanceTracker() {
        this.startTime = new AtomicLong(0);
        this.endTime = new AtomicLong(0);
        this.processedItems = new AtomicInteger(0);
        this.errors = new AtomicInteger(0);
        this.inputStockFinalLevel = new AtomicInteger(0);
        this.outputStockFinalLevel = new AtomicInteger(0);
        this.intermediateStock1FinalLevel = new AtomicInteger(0);
        this.intermediateStock2FinalLevel = new AtomicInteger(0);
    }

    public void startTracking() {
        startTime.set(System.currentTimeMillis());
    }

    public void stopTracking() {
        endTime.set(System.currentTimeMillis());
    }

    public long getExecutionTime() {
        return endTime.get() - startTime.get();
    }

    public void incrementProcessedItems() {
        processedItems.incrementAndGet();
    }

    public void incrementErrors() {
        errors.incrementAndGet();
    }

    public void setFinalStockLevels(int input, int output, int intermediate1, int intermediate2) {
        inputStockFinalLevel.set(input);
        outputStockFinalLevel.set(output);
        intermediateStock1FinalLevel.set(intermediate1);
        intermediateStock2FinalLevel.set(intermediate2);
    }

    public void setFinalStockLevels(int input, int output) {
        setFinalStockLevels(input, output, 0, 0);
    }

    public int getProcessedItems() {
        return processedItems.get();
    }

    public int getErrors() {
        return errors.get();
    }

    public int getInputStockFinalLevel() {
        return inputStockFinalLevel.get();
    }

    public int getOutputStockFinalLevel() {
        return outputStockFinalLevel.get();
    }

    public int getIntermediateStock1FinalLevel() {
        return intermediateStock1FinalLevel.get();
    }

    public int getIntermediateStock2FinalLevel() {
        return intermediateStock2FinalLevel.get();
    }

    public void printReport() {
        System.out.println("=== Performance Report ===");
        System.out.println("Execution Time: " + getExecutionTime() + " ms");
        System.out.println("Processed Items: " + getProcessedItems());
        System.out.println("Errors: " + getErrors());
        System.out.println("Input Stock Final Level: " + getInputStockFinalLevel());
        System.out.println("Output Stock Final Level: " + getOutputStockFinalLevel());
        System.out.println("Intermediate Stock 1 Final Level: " + getIntermediateStock1FinalLevel());
        System.out.println("Intermediate Stock 2 Final Level: " + getIntermediateStock2FinalLevel());
        System.out.println("=========================");
    }
}

