// Thread-safe stock implementation with performance tracking
class Stock {
    private Item[] items;
    private int capacity;
    private int size;
    private int head;
    private int tail;
    private AtomicInteger putOperations;
    private AtomicInteger takeOperations;

    public Stock(int capacity) {
        this.capacity = capacity;
        this.items = new Item[capacity];
        this.size = 0;
        this.head = 0;
        this.tail = 0;
        this.putOperations = new AtomicInteger(0);
        this.takeOperations = new AtomicInteger(0);
    }

    public synchronized boolean put(Item item) {
        if (size >= capacity) {
            return false; // Stock is full
        }
        items[tail] = item;
        tail = (tail + 1) % capacity;
        size++;
        putOperations.incrementAndGet();
        notifyAll(); // Notify waiting consumers
        return true;
    }

    public synchronized Item take() throws InterruptedException {
        while (size <= 0) {
            wait(); // Wait until items are available
        }
        Item item = items[head];
        items[head] = null; // Help GC
        head = (head + 1) % capacity;
        size--;
        takeOperations.incrementAndGet();
        notifyAll(); // Notify waiting producers
        return item;
    }

    public synchronized int size() {
        return size;
    }

    public synchronized boolean isEmpty() {
        return size <= 0;
    }

    public synchronized boolean isFull() {
        return size >= capacity;
    }

    public int getPutOperations() {
        return putOperations.get();
    }

