// Base EnhancedFactory class
abstract class EnhancedFactory {
    protected Stock inputStock;
    protected Stock outputStock;
    protected int totalItemsToProcess;
    protected AtomicLong startTime;
    protected AtomicLong endTime;
    protected AtomicInteger processedItems;
    protected AtomicInteger errors;

    public EnhancedFactory(int inputStockSize, int outputStockSize, int totalItemsToProcess) {
        this.inputStock = new Stock(inputStockSize);
        this.outputStock = new Stock(outputStockSize);
        this.totalItemsToProcess = totalItemsToProcess;
        this.startTime = new AtomicLong(0);
        this.endTime = new AtomicLong(0);
        this.processedItems = new AtomicInteger(0);
        this.errors = new AtomicInteger(0);
    }

    public synchronized boolean addToInputStock(Item item) {
        return inputStock.put(item);
    }

    public synchronized Item takeFromOutputStock() throws InterruptedException {
        return outputStock.take();
    }

    public abstract FactoryPerformance runSimulation() throws InterruptedException;

    public int getRemainingInputStock() {
        return inputStock.size();
    }

    protected void startTracking() {
        startTime.set(System.currentTimeMillis());
    }

    protected void stopTracking() {
        endTime.set(System.currentTimeMillis());
    }

    protected long getExecutionTime() {
        return endTime.get() - startTime.get();
    }
}

