                        Item item = inputStock.take();
                        if (useFirst) {
                            intermediateStock1.put(item);
                        } else {
                            intermediateStock2.put(item);
                        }
                        useFirst = !useFirst;
                        processed++;
                    } catch (InterruptedException e) {
                        errors.incrementAndGet();
                        Thread.currentThread().interrupt();
                        break;
