                errors.incrementAndGet();
            }
        });

        // First parallel workshop
        Thread workshop1 = new Thread(() -> {
            try {
                int processed = 0;
                while (processed < totalItemsToProcess/2 + 1) {
                    if (!intermediateStock1.isEmpty()) {
                        try {
                            Item item = intermediateStock1.take();
                            Thread.sleep(100); // Simulate processing
