                            processed++;
                        } catch (InterruptedException e) {
                            errors.incrementAndGet();
                            Thread.currentThread().interrupt();
                            break;
                        }
                    }
                }
            } finally {
                stopTracking();
            }
        });

        splitter.start();
        workshop1.start();
        workshop2.start();

        // Wait for processing to complete
